        'n_portfolio' => 'પોર્ટફોલિયો અને ચાર્ટ',
        'n_connections' => 'કનેક્શન',
        'd_goal' => 'પૂર્ણ થવું એટલે શું તે કહેતું એક વાક્ય. પ્રોજેક્ટમાં બાકીનું બધું ત્યાં પહોંચવા માટે છે.',
        'd_case' => 'પ્રોજેક્ટ કરવા જેવો કેમ છે: લાભ, ખર્ચ, જોખમ. બોર્ડ પહેલા ગેટ પર તેના પર નિર્ણય લે છે.',
        'd_benefits' => 'પ્રોજેક્ટે શું સુધારવું જોઈએ, શરૂઆતના બિંદુથી ટાર્ગેટ તરફ માપેલું - અને બંધ થયા પછી તેની સમીક્ષા થાય છે, કારણ કે મોટા ભાગના લાભ ત્યારે જ આવે છે.',
        'd_scope' => 'ડિલિવરેબલ્સ, દરેક Must, Should, Could અથવા Won\'t. વસ્તુઓને નમ્રતાથી ના કહેવાની આ રીત છે.',
        'd_milestones' => 'પ્રોજેક્ટે વચન આપેલી તારીખો. એક ચૂકી જવાથી હેલ્થ એમ્બર થઈ જાય છે અને પ્રોજેક્ટ મેનેજરને જાણ કરે છે.',
        'd_stages' => 'કામને કેવી રીતે વહેંચવામાં આવે છે: ફેઝ (Simple), અંતે ગેટ સાથે તબક્કા (Staged) અથવા બે-અઠવાડિયાની સ્પ્રિન્ટ (Agile). એ જ વસ્તુ, અલગ દૃષ્ટિકોણ.',
        'd_tasks' => 'વાસ્તવિક કામ - સામાન્ય FreeITSM ટાસ્ક, તેથી તે Tasks બોર્ડ પર અને લોકોની યાદીઓમાં દેખાય છે.',
        'd_deps' => 'આ ટાસ્ક પેલું પૂરું થાય ત્યાં સુધી શરૂ થઈ શકતું નથી. તે ટાઇમલાઇનને તેના તીર આપે છે અને ક્રિટિકલ પાથ શોધી કાઢે છે.',
        'd_timeline' => 'ગેન્ટ ચાર્ટ: કૅલેન્ડર પર તબક્કા, ટાસ્ક અને માઇલસ્ટોન, ક્રિટિકલ પાથ અને ટકરાતી તારીખો સાથે.',
        'd_capacity' => 'દરેક ટાસ્ક પર અંદાજિત કલાકો, તે કરનારા લોકોમાં વહેંચાયેલા, જેથી નુકસાન થાય તે પહેલાં તમે જોઈ શકો કે કોના પર વધુ ભાર છે.',
        'd_people' => 'પ્રોજેક્ટ પર કોણ છે - વિશ્લેષકો, આખી ટીમો અને People મોડ્યુલના લોકો - અને દરેકની ભૂમિકા.',
        'd_raci' => 'દરેક ડિલિવરેબલ માટે: કોણ કરે છે, કોણ જવાબદાર છે, કોને પૂછવામાં આવે છે અને કોને જણાવવામાં આવે છે.',
        'd_stakeholders' => 'હિત ધરાવતા દરેક જણ, પાવર અને રસ પ્રમાણે ગોઠવાયેલા, તેઓ ક્યાં ઊભા છે અને તેમને કેવી રીતે માહિતગાર રાખવામાં આવે છે તે સાથે.',
        'd_raid' => 'જોખમો, ધારણાઓ, સમસ્યાઓ, ડિપેન્ડન્સી, નિર્ણયો અને પાઠ, શું ખોટું થઈ શકે તેના હીટ મેપ સાથે.',
        'd_gates' => 'તબક્કાના અંતે કોઈ કહે છે આગળ વધો, શરતો સાથે આગળ વધો અથવા અટકો. ચેકલિસ્ટ કહે છે કે પહેલાં શું સાચું હોવું જોઈએ.',
        'd_tolerances' => 'બોર્ડ પાસે પાછા જવું પડે તે પહેલાં પ્રોજેક્ટ કેટલો ભટકી શકે - મોડા દિવસો, જોખમ સ્કોર, બજેટથી વધુ %.',
        'd_health' => 'લીલો, એમ્બર અથવા લાલ, તમે જ્યારે પણ જુઓ ત્યારે પ્લાન પરથી ગણાયેલો: મુદત વીતેલું કામ, ચૂકી ગયેલા માઇલસ્ટોન, ટોલરન્સ, ટાર્ગેટ તારીખ.',
        'd_budget' => 'આયોજિત સામે ખર્ચેલું, લાઇન પ્રમાણે, તારીખો સાથે - જેથી તમે સમય સાથે પૈસા અને અંત સુધીનું ફોરકાસ્ટ જોઈ શકો.',
        'd_earned' => 'જે આયોજન હતું, પૂરા થયેલા કામની કિંમત અને તેનો ખર્ચ સરખાવે છે: શું પૂરા થયેલા કામ માટે તમે બજેટથી વધુ છો, અને પાછળ છો?',
        'd_change' => 'સંમત પ્લાનની બેઝલાઇન, અને પ્લાન ખસે તે પહેલાં મંજૂર અથવા નકારાયેલી ચેન્જ વિનંતીઓ.',
        'd_reports' => 'હાઇલાઇટ, એક્સેપ્શન, ચેકપોઇન્ટ અને ક્લોઝર રિપોર્ટ - તમે લખેલા અથવા પ્રોજેક્ટના પોતાના ડેટામાંથી AI એ ડ્રાફ્ટ કરેલા, મંજૂર થયેલા, પછી ઈમેઇલ કરેલા.',
        'd_alerts' => 'હેલ્થ બદલાય, માઇલસ્ટોન નજીક આવે, મંજૂરી બહુ લાંબી રાહ જુએ અથવા ટાસ્કની મુદત વીતી જાય ત્યારે બેલ યોગ્ય વ્યક્તિને જણાવે છે.',
        'd_portfolio' => 'એકસાથે દરેક પ્રોજેક્ટ: કાર્ડ, રોડમેપ અને પ્રોજેક્ટ્સ આખાના ચાર્ટ, પ્રાથમિકતા અથવા તારીખ પ્રમાણે ગોઠવેલા.',
        'd_connections' => 'પ્રોજેક્ટ જેને સ્પર્શે છે તે ચેન્જ, ટિકિટ, સમસ્યાઓ, સાધનો, કરારો, CI અને લેખો - બંને રીતે લિંક કરેલા.',
        'w_goal' => 'પ્રોજેક્ટનું ફોર્મ અને તેનું બેનર',
        'w_case' => 'Gates ટેબ',
