        'w_deps' => 'Timeline - ટાસ્ક પરનું લિંક બટન',
        'w_timeline' => 'Timeline ટેબ',
        'w_capacity' => 'Plan ટેબ (અંદાજ), અને Projects ની ટોચે Capacity',
        'w_people' => 'People ટેબ',
        'w_raci' => 'RACI ટેબ',
