        'w_tolerances' => 'Gates ટેબ',
        'w_health' => 'બેનર, Overview અને દરેક કાર્ડ',
        'w_budget' => 'Budget ટેબ',
        'w_earned' => 'Budget ટેબ',
        'w_change' => 'Change control ટેબ',
        'w_reports' => 'Reports ટેબ, અને Overview નું બ્રીફિંગ',
        'w_alerts' => 'બેલ; રિમાઇન્ડર માટે Projects - Settings',
        'w_portfolio' => 'Projects હોમ - Cards, Roadmap, Charts',
        'w_connections' => 'Connections ટેબ, અને દરેક રેકોર્ડનું પોતાનું પેજ',
        's1_title' => 'તેની શરૂઆત ધ્યેયથી થાય છે',
        's1_text' => 'ઓફિસ ખસેડવી: "આવતા ક્વાર્ટરના અંત સુધીમાં તમામ 40 સ્ટાફ Bradford થી કામ કરતો હોય." જો બોર્ડની મંજૂરી જોઈતી હોય, તો બિઝનેસ કેસ કહે છે કે તે શા માટે કરવા જેવું છે - અને તે જે લાભોનું વચન આપે છે તે જ તમે અંતે માપશો.',
        's2_title' => 'તેને ટુકડાઓમાં વહેંચો',
        's2_text' => 'ચાર તબક્કા: સર્વે અને ડિઝાઇન, નેટવર્ક બનાવવું, ખસેડવાનો વીકએન્ડ, સ્થિર થવું. માઇલસ્ટોન તમે વચન આપેલી તારીખો દર્શાવે છે - નેટવર્ક લાઇવ, ખસેડવાનો દિવસ.',
        's3_title' => 'કામનું આયોજન કરો',
        's3_text' => 'દરેક તબક્કામાં ટાસ્ક મૂકો. કેટલાક બીજાની રાહ જુએ છે - કેબલિંગ પહેલાં સ્વિચ લગાવી શકાતા નથી - અને તે ડિપેન્ડન્સી ટાઇમલાઇનના તીર દોરે છે અને ક્રિટિકલ પાથ શોધે છે.',
        's4_title' => 'કોણ શું કરે છે',
        's4_text' => 'લોકોને ઉમેરો, તેમને ભૂમિકાઓ આપો, અને ટાસ્કનો અંદાજ લગાવો જેથી Capacity બતાવે કે કોના પર ભાર છે. મોટા પ્રોજેક્ટ પર, RACI કહે છે કે દરેક ડિલિવરેબલ માટે કોણ જવાબદાર છે, અને સ્ટેકહોલ્ડર મેપ કહે છે કે કોને ખુશ રાખવા.',
        's5_title' => 'શું સામેલ છે તે નક્કી કરો',
        's5_text' => 'સ્કોપ યાદી આપે છે કે શું ડિલિવર થશે: દરેક ડેસ્ક પેચ થવું એ Must છે; રિસેપ્શનમાં સાઇનેજ એ Could છે. વહેલું મોટેથી કહી દેવાથી પછીની દલીલો બચે છે.',
        's6_title' => 'શું ખોટું થઈ શકે તેના પર નજર રાખો',
        's6_text' => 'RAID લોગમાં સ્વિચ મોડા આવવાનું જોખમ, ઇન્ટરનેટ લાઇન પાછળ ગઈ તે સમસ્યા હોય છે. ટોલરન્સ કહે છે કે કેટલું ખરાબ વધુ પડતું છે - અને પ્લાન કહે ત્યારે હેલ્થ જાતે જ એમ્બર અથવા લાલ થઈ જાય છે.',
        's7_title' => 'પૈસાને અનુસરો',
        's7_text' => 'તારીખો સાથેની બજેટ લાઇન સમય સાથે ખર્ચ અને ફોરકાસ્ટ બતાવે છે. અર્ન્ડ વેલ્યુ તેને વાસ્તવમાં થયેલા કામ સાથે સરખાવે છે.',
        's8_title' => 'ગેટ પર નિર્ણય લો',
        's8_text' => 'ખસેડવાના વીકએન્ડ પહેલાં, ગેટની ચેકલિસ્ટ પૂર્ણ થવી જોઈએ - યુઝર ટેસ્ટિંગ સાઇન-ઓફ, બેકઆઉટ પ્લાન જોડેલો - પછી કોઈ કહે છે આગળ વધો.',
        's9_title' => 'જ્યારે પ્લાન ખસેડવો પડે',
        's9_text' => 'કોઈ બીજા બે મીટિંગ રૂમમાં સ્ક્રીન ઇચ્છે છે. ચેન્જ વિનંતી કહે છે કે તેનો દિવસો અને પૈસામાં ખર્ચ શું છે; તેને મંજૂર કરવાથી નવી બેઝલાઇન બને છે, જેથી પ્લાન કેટલો ખસ્યો છે તે તમે હંમેશા જોઈ શકો.',
        's10_title' => 'લોકોને જણાવો',
        's10_text' => 'દર મહિને એક હાઇલાઇટ રિપોર્ટ - ઇચ્છો તો AI એ ડ્રાફ્ટ કરેલો, તમે મંજૂર કરેલો, સ્ટેકહોલ્ડર્સને ઈમેઇલ કરેલો. જે વસ્તુઓ અટકાવી રહ્યું હોય તેને બેલ યાદ અપાવે છે, અને પોર્ટફોલિયો દરેક પ્રોજેક્ટ બાજુ-બાજુમાં બતાવે છે.',
        's11_title' => 'તેને FreeITSM ના બાકીના ભાગ સાથે જોડો',
        's11_text' => 'નવા સ્વિચ માટેનો ચેન્જ, ખસેડવાથી થતી ટિકિટ, કેબલિંગ ફર્મ સાથેનો કરાર લિંક કરો. તે દરેક રેકોર્ડ પોતાની બાજુથી પણ પ્રોજેક્ટ બતાવે છે.',
