        'ai_intro' => 'અહીં પ્રદાતા સેટ કર્યા પછી, પ્રોજેક્ટની ઝાંખી ટૂંકી બ્રીફિંગ આપે છે - આ અઠવાડિયે શેના પર ધ્યાન આપવું જરૂરી છે - અને તેનો રિપોર્ટ્સ ટૅબ હાઇલાઇટ, અપવાદ, ચેકપોઇન્ટ અને સમાપન રિપોર્ટનો ડ્રાફ્ટ બનાવે છે. AI ફક્ત સૂચવે છે: પ્રોજેક્ટ મેનેજર મંજૂર ન કરે ત્યાં સુધી રિપોર્ટ ડ્રાફ્ટ જ રહે છે.',
        'ai_privacy' => 'શું મોકલાય છે: પ્રોજેક્ટનું નામ, ધ્યેય, સારાંશ, બિઝનેસ કેસ, તારીખો, હેલ્થ અને ટોલરન્સ, તબક્કા અને ગેટ નિર્ણયો, ડિલિવરેબલ્સ, ટાસ્કના શીર્ષક અને તે કોને સોંપાયા છે, RAID લોગ, બજેટના કુલ આંકડા, જાહેર કરાયેલો વિક્ષેપ અને તાજેતરનો ઇતિહાસ - ફક્ત તે જ જે પૂછનાર વ્યક્તિ જોઈ શકે છે. કોઈ Brief me અથવા Draft દબાવે ત્યાં સુધી કંઈ મોકલાતું નથી.',
