        'hero_heading' => 'પ્રોજેક્ટ્સ',
        'hero_sub' => 'તમારી પાસે પહેલેથી હોય તેવા ટાસ્ક પર IT પ્રોજેક્ટ્સનું આયોજન કરો અને ચલાવો, અને એક નજરે જુઓ કે દરેક પ્રોજેક્ટ ટ્રેક પર છે કે નહીં.',
        'overview' => [
            'nav' => 'તે શું છે',
            'title' => 'પ્રોજેક્ટ્સ શું છે',
            'intro' => 'મોટા કામો માટે એક જગ્યા - જે ડઝનબંધ ટાસ્કથી બનેલા હોય.',
            'p1' => 'ઓફિસ ખસેડવી, લેપટોપ બદલવા કે મેઇલ માઇગ્રેશન એક ટાસ્ક માટે ખૂબ મોટું અને સ્પ્રેડશીટમાં રાખવા માટે ખૂબ મહત્વનું છે. પ્રોજેક્ટ તેની પાછળના ટાસ્ક એકઠા કરે છે, તેમને ફેઝમાં વહેંચે છે, અને તે ટાસ્ક પરથી જ ગણે છે કે કેટલું કામ થયું અને તે મુશ્કેલીમાં છે કે નહીં.',
            'p2' => 'તમારો પોતાનો પ્રોજેક્ટ બનાવતાં પહેલાં તેને કામ કરતો જોવા માટે, System ખોલી શકે તેવી વ્યક્તિ **System - Demo data - Tasks and Projects** ઇમ્પોર્ટ કરી શકે છે: નવ પ્રોજેક્ટ જે ચલાવવાની દરેક રીત અને દરેક સ્થિતિ આવરી લે છે, તેમના ટાસ્ક, ચાર્ટ અને ઇતિહાસ સાથે. પહેલાં Assets, Changes, Tickets, Contracts, Knowledge અને CMDB ઇમ્પોર્ટ કરો અને પ્રોજેક્ટ્સ તે રેકોર્ડ્સ સાથે પણ લિંક થશે. ફરી ઇમ્પોર્ટ કરવાથી ફક્ત ડેમો પ્રોજેક્ટ્સ બદલાય છે.',
            'card_plan_title' => 'એક યોજના',
