            'card_tasks_title' => 'સાચા ટાસ્ક',
            'card_tasks_desc' => 'પ્રોજેક્ટનું કામ સામાન્ય ટાસ્ક જ છે, તેથી તે કરનાર લોકો માટે ટાસ્ક બોર્ડ પર દેખાય છે.',
