        'map' => [
            'nav' => 'તે કેવી રીતે જોડાયેલું છે',
            'title' => 'તે કેવી રીતે જોડાયેલું છે',
            'intro' => 'પ્રોજેક્ટનો દરેક ભાગ, અને શું શેને પોષે છે - તેને ફંફોસો, અથવા પ્રોજેક્ટને લક્ષ્યથી લાભો સુધી ચાલીને જુઓ.',
            'open' => 'મેપ ખોલો',
            'open_walk' => 'પ્રોજેક્ટમાંથી પસાર થાઓ',
            'p1' => 'તેનું પોતાનું પેજ છે, તેથી મેપને આખી સ્ક્રીન મળે છે - ખાલી પોર્ટફોલિયો અને Toolbox માંથી પણ લિંક થયેલ છે. કોઈપણ બોક્સ પસંદ કરો અને જુઓ કે તે શું છે, તમને તે ક્યાં મળે છે અને કયું ટૂલ તેને ચાલુ કરે છે; લીટીઓ અને યાદીઓ બતાવે છે કે તે શેને પોષે છે અને તેને શું પોષે છે. **પ્રોજેક્ટમાંથી પસાર થાઓ** ઓફિસ ખસેડવાના કામને તેના લક્ષ્યથી લાભો સુધી અનુસરે છે, બાર પગલાંમાં (એરો કીથી પણ પગલાં આગળ વધે છે). **પ્રોજેક્ટ શેનાથી શરૂ થાય છે તે બતાવો** ચલાવવાની રીત શરૂઆતમાં જે ભાગો છોડી દે છે તેમને ઝાંખા કરે છે - Simple પ્રોજેક્ટ બહુ ઓછાથી શરૂ થાય છે, અને તેના Overview પરનું Toolbox પ્રોજેક્ટને જરૂર પડે ત્યારે બાકીનું ઉમેરે છે.',
            'noscript' => 'ઇન્ટરેક્ટિવ મેપ માટે JavaScript જરૂરી છે. દરેક ભાગનું વર્ણન નીચેના વિભાગોમાં પણ છે.',
        ],
        'portfolio' => [
            'nav' => 'પોર્ટફોલિયો',
            'title' => 'પોર્ટફોલિયો',
            'intro' => 'દરેક પ્રોજેક્ટ એક કાર્ડ તરીકે.',
            'p1' => 'પ્રોજેક્ટ્સ પોર્ટફોલિયો પર ખુલે છે: દરેક પ્રોજેક્ટ માટે એક કાર્ડ, તેના માલિકે પસંદ કરેલા રંગ અને આઇકન સાથે. રિંગ બતાવે છે કે કેટલું કામ પૂર્ણ થયું અને તે હેલ્થ પ્રમાણે રંગાયેલી હોય છે; નીચે લક્ષ્ય તારીખ, તેનું નેતૃત્વ કોણ કરે છે અને હાલમાં શું ચાલે છે તે હોય છે.',
            'p2' => 'ડાબી બાજુના દૃશ્યો સામાન્ય પ્રશ્નોના જવાબ આપે છે - શું ચાલુ છે, હું કયા ચલાવું છું, કયાને ધ્યાન જોઈએ છે, શું પૂર્ણ થયું - અને ઉપરની ટાઇલ્સ તે બધામાં મહત્વની બાબતો ગણે છે. પ્રોજેક્ટ શરૂ કરવા **New** દબાવો.',
            'p3' => 'ટાઇલ્સની નીચે, એક બાર બતાવે છે કે ચાલુ પ્રોજેક્ટ્સ કેવા છે - ટ્રેક પર, જોખમમાં, ટ્રેકની બહાર, કે હજી હેલ્થ નથી - દરેકની ગણતરી સાથે. **Sort** કાર્ડને લક્ષ્ય તારીખ, પ્રાથમિકતા, હેલ્થ કે નામ પ્રમાણે ગોઠવે છે (પ્રારંભિક ક્રમ Projects - Settings - General માં સેટ થાય છે), અને **Roadmap** કાર્ડની જગ્યાએ કેલેન્ડર પર દરેક પ્રોજેક્ટ માટે એક બાર મૂકે છે: તેની શરૂઆતથી લક્ષ્ય સમાપ્તિ સુધી, પૂર્ણ થયેલા કામ માટે ઘેરો, તેના આગામી માઇલસ્ટોન સાથે. દરેક પ્રોજેક્ટની એક **પ્રાથમિકતા** હોય છે - Low, Medium, High કે Critical, અથવા સેટિંગ્સમાંથી તમારા પોતાના ચાર શબ્દો - જે Medium ન હોય ત્યારે તેના કાર્ડ પર દેખાય છે.',
            'p4' => '**Charts** (Cards અને Roadmap ની બાજુમાં) દૃશ્યમાંના પ્રોજેક્ટ્સને સાથે દોરે છે: પ્રોજેક્ટ પ્રમાણે પ્રગતિ, બજેટ સામે વાસ્તવિક (દરેક ચલણ માટે એક ચાર્ટ, વધુ ખર્ચ નોંધાયેલ), દરેક ખુલ્લા જોખમનો રિસ્ક હીટ મેપ - તેમની યાદી જોવા માટે ચોરસ પસંદ કરો - અને પ્રોજેક્ટ્સ આખામાં દરેક માઇલસ્ટોન, પહોંચેલ, ચૂકી ગયેલ કે આવનાર. દરેક ચાર્ટ સાથે એક **Table** હોય છે.',
            'p5' => '**Export** દૃશ્યમાંના પ્રોજેક્ટ્સને - તમે પસંદ કરેલા દૃશ્ય, શોધ અને ક્રમ પછી - Excel વર્કબુક કે CSV ફાઇલ તરીકે ડાઉનલોડ કરે છે: સ્થિતિ, પ્રાથમિકતા, હેલ્થ, પ્રગતિ, પ્રોજેક્ટ મેનેજર, તારીખો, ટાસ્ક, માઇલસ્ટોન અને દરેક પ્રોજેક્ટના પોતાના ચલણમાં બજેટ. જે દૃશ્યમાં કોઈ પ્રોજેક્ટ ન હોય તે કંઈ નિકાસ કરતું નથી.',
        ],
        'project' => [
            'nav' => 'પ્રોજેક્ટ',
            'title' => 'પ્રોજેક્ટનું પેજ',
            'intro' => 'બેનર, પછી Overview, Plan, Timeline, પ્રોજેક્ટના ટૂલ્સ, Documents, Reports, Connections અને History.',
            'p1' => 'બેનર પ્રોજેક્ટનું નામ, તેનું લક્ષ્ય (પૂર્ણ થવાનો અર્થ શું), તેની સ્થિતિ, તે કેવી રીતે ચલાવાય છે, કોણ તેનું નેતૃત્વ કરે છે, તેની તારીખો અને હેલ્થ રિંગ બતાવે છે. **Edit** તેમાંનું કંઈપણ બદલે છે, સ્થિતિ સહિત: પ્રોજેક્ટને Closed પર સેટ કરવાથી, જો કોઈએ વાસ્તવિક સમાપ્તિ સેટ કરી ન હોય તો, આજની તારીખ ભરાઈ જાય છે.',
            'p2' => 'Overview આંકડા એકઠા કરે છે, **Progress over time** (બર્નઅપ: પ્લાનનો દરેક ટાસ્ક અને તેમાંથી પૂર્ણ થયેલા, દિવસ કે અઠવાડિયા પ્રમાણે, લક્ષ્ય સમાપ્તિ ચિહ્નિત સાથે - ફક્ત તે જોવા ફેઝ પસંદ કરો, અથવા ટાસ્કને બદલે અંદાજિત કલાકો ગણો), હાલમાં શું ચાલે છે, આગળ શું નિયત છે અને તાજેતરના ફેરફારો. Plan અને Timeline પછી પ્રોજેક્ટ જે ટૂલ વાપરે છે તેમાંના દરેક માટે એક ટૅબ આવે છે - People, Scope, RACI, RAID, Gates, Budget, Change control અને Benefits, નીચે વર્ણવેલ છે - પછી **Documents** (પ્લાન, ડિઝાઇન, સાઇન-ઑફ પત્રો: અપલોડ કરેલી ફાઇલ કે તે જ્યાં છે ત્યાંની લિંક), Reports અને Connections. બધાં ટૂલ ચાલુ હોય ત્યારે ટૅબ બાર બાજુમાં સ્ક્રોલ થાય છે. History જે કંઈ બદલાયું અને કોણે બદલ્યું તે બધું યાદી કરે છે.',
            'p3' => '**Progress over time** (બર્નઅપ, અથવા **Burndown** - આદર્શ રેખા સામે અંત સુધી શું બાકી છે) ની નીચે Overview માં **Task status** (દરેક તબક્કા માટે એક બાર: તમારી દરેક ટાસ્ક સ્થિતિમાં કેટલા ટાસ્ક છે, કેટલા મોડા છે કે બીજા ટાસ્કની રાહ જુએ છે), **Progress by stage**, અને **Flow over time** - કમ્યુલેટિવ ફ્લો ડાયાગ્રામ: દરેક સ્થિતિમાં ટાસ્ક, દિવસે દિવસે. જે પટ્ટો પહોળો થતો જ રહે તે ત્યાં ઢગલો થતું કામ છે. સ્થિતિઓ 3.3.0 થી દિવસમાં એક વાર નોંધાય છે; તે પહેલાં ફક્ત ટાસ્ક ક્યારે બન્યા અને પૂર્ણ થયા તે જ જાણીતું છે, રાખોડી રંગમાં બતાવેલ.',
            'p4' => 'ચાર્ટ્સની ઉપર, Overview કહે છે કે કોને ધ્યાન આપવાની જરૂર છે, દરેક ફક્ત લાગુ પડે ત્યારે: ચૂકી ગયેલ માઇલસ્ટોન, તારીખ વીતી ગયેલ ડિપેન્ડન્સી કે નિર્ણય, બાકી લાભ સમીક્ષાઓ, નિર્ણયની રાહ જોતી ચેન્જ વિનંતીઓ અને RAID લોગ પર એસ્કેલેટ થયેલું કંઈપણ - દરેક સાથે **See all**. પછી જે પ્રોજેક્ટ પ્રસ્તાવિત હતો તેના પર **Proposal** પેનલ (રાહ જોતી વખતે Approve અને Reject), **Toolbox** (Tools જુઓ) અને AI **Briefing**.',
        ],
        'plan' => [
            'nav' => 'યોજના',
            'title' => 'યોજના બનાવવી',
            'intro' => 'પહેલાં ફેઝ, પછી ટાસ્ક.',
            'p1' => 'Plan ટૅબ દરેક ફેઝ (કે તબક્કો, કે સ્પ્રિન્ટ) ને ટાસ્કની લેન તરીકે બતાવે છે, તેની તારીખો, સ્થિતિ અને તેના કેટલા ટાસ્ક પૂર્ણ થયા તે સાથે. હજી કોઈ ફેઝમાં ન હોય તેવા ટાસ્ક તળિયે રહે છે.',
            'p2' => 'લેનની નીચેના બોક્સમાં ટાસ્ક ટાઇપ કરીને ઉમેરો - ઇચ્છો તો કોણ કરશે અને ક્યારે નિયત છે તે પસંદ કરો. ટાસ્કને ખસેડવા બીજી લેન પર ખેંચો, અથવા લેનનો ક્રમ ગોઠવવા તેની અંદર ઉપર-નીચે ખેંચો - એક રેખા બતાવે છે કે તે ક્યાં ઉતરશે. કીબોર્ડથી, ટાસ્કના હેન્ડલ પર ફોકસ કરો અને ઉપર કે નીચેનું એરો દબાવો; ફોન પર, દરેક ટાસ્કના મૂવ બટનમાં Up અને Down છે. ટાસ્ક ખોલવા તેના પર ક્લિક કરો, તે ટાસ્ક બોર્ડ પર ખુલે છે, જ્યાં તે અન્ય કોઈપણ ટાસ્કની જેમ સંપાદિત થાય છે.',
            'p3' => 'ફેઝ પરનું કામ શરૂ થાય ત્યારે તેના પર **Start** અને પૂર્ણ થાય ત્યારે **Finish** દબાવો. ટાસ્ક પંક્તિના અંતે આવેલું ક્રોસ તેને પ્રોજેક્ટમાંથી બહાર કાઢે છે; ટાસ્ક પોતે રહે છે.',
            'p4' => 'માઇલસ્ટોન એ તારીખો છે જેનું પ્રોજેક્ટ વચન આપે છે - ખસેડવાનો દિવસ, ગો-લાઇવ, બોર્ડની મંજૂરી. એક ઉમેરવા Plan ટૅબ પર **Milestone** દબાવો, ફેઝમાં કે આખા પ્રોજેક્ટ માટે. દરેક ફેઝ તેના માઇલસ્ટોન હીરા તરીકે બતાવે છે; તે થાય ત્યારે **Reached** પર ટિક કરો. જે માઇલસ્ટોનની તારીખ પહોંચ્યા વિના વીતી જાય તે ચૂકી ગયેલ ગણાય છે, અને પ્રોજેક્ટને એમ્બર બનાવે છે.',
            'step1' => 'પોર્ટફોલિયો પર **New** દબાવો, પ્રોજેક્ટને નામ અને લક્ષ્ય આપો, અને તમે તેને કેવી રીતે ચલાવો છો તે પસંદ કરો.',
            'step2' => 'Plan ટૅબ પર, કામ જેમાં વહેંચાય છે તે ફેઝ ઉમેરો.',
            'step3' => 'દરેક ફેઝ નીચે ટાસ્ક ઉમેરો, કોણ કરશે અને ક્યારે તે સાથે.',
            'step4' => 'પહેલો ફેઝ શરૂ કરો. ત્યારથી રિંગ અને હેલ્થ પોતાની રીતે અપ ટુ ડેટ રહે છે.',
        ],
        'timeline' => [
            'nav' => 'Timeline',
            'title' => 'Timeline',
            'intro' => 'આખી યોજના કેલેન્ડર સામે.',
            'p1' => 'Timeline ટૅબ યોજનાને Gantt ચાર્ટ તરીકે દોરે છે: દરેક ફેઝ, તબક્કો કે સ્પ્રિન્ટ તેની તારીખો પર એક પટ્ટો છે, તેના ટાસ્ક શરૂઆતથી નિયત તારીખ સુધીના બાર છે, અને માઇલસ્ટોન હીરા છે - પહોંચેલ હોય તો લીલા, ચૂકી ગયેલ હોય તો લાલ. એક રેખા આજને અને બીજી લક્ષ્ય સમાપ્તિને ચિહ્નિત કરે છે.',
            'p2' => 'માઉસ વડે, ટાસ્ક કે ફેઝ ખસેડવા બારને ખેંચો, અથવા તે ક્યારે શરૂ કે પૂર્ણ થાય તે બદલવા કોઈપણ છેડો ખેંચો; માઇલસ્ટોન ખસેડવા હીરો ખેંચો. દરેક ફેરફાર તરત સાચવાય છે અને તેને હાથે સંપાદિત કરવા જેવા જ નિયમોમાંથી પસાર થાય છે, તેથી ટાસ્ક બોર્ડ, કૅલેન્ડર અને હેલ્થ તેને અનુસરે છે. તેના બદલે ખોલવા માટે બાર પર ક્લિક કરો. તારીખ વિનાના ટાસ્ક દોરાતા નથી; ટૅબ કહે છે કે કેટલા છે.',
            'p3' => 'ઝૂમ કરવા **Days**, **Weeks** કે **Months** પસંદ કરો. ફોન પર ચાર્ટ બાજુમાં સ્ક્રોલ થાય છે; વસ્તુઓ ખસેડવા માટે તેમને ટૅપ કરીને તારીખો બદલવામાં આવે છે.',
            'p4' => '**Dependencies.** ટાસ્કની પંક્તિ પરનું લિંક બટન કહે છે કે તે શેની રાહ જુએ છે: એક ટાસ્ક બીજો પૂર્ણ થાય ત્યાં સુધી શરૂ થઈ શકતો નથી, વૈકલ્પિક રીતે કેટલાક દિવસના અંતર સાથે. ચાર્ટ પર તીરો તેમને જોડે છે - જ્યાં યોજના અથડાય ત્યાં લાલ અને તૂટક (તે બીજો પૂર્ણ થવાનો હોય તે પહેલાં શરૂ થાય છે). **Critical path** એવા ટાસ્કને અલગ તારવે છે જેમાં કોઈ છૂટ નથી - તે જે દિવસે પાછળ પડે, સમાપ્તિ પણ પાછળ પડે - અને બાકીનાને ઝાંખા કરે છે. લૂપ નકારવામાં આવે છે. Plan પર ટાસ્ક જે વસ્તુની રાહ જુએ છે તે અપૂર્ણ હોય ત્યારે **Waiting on 1** બતાવે છે, અને તેની તારીખો કામ ન કરી શકે ત્યારે **Clash**.',
        ],
        'capacity' => [
            'nav' => 'કેપેસિટી',
            'title' => 'અંદાજ અને કેપેસિટી',
            'intro' => 'આગામી અઠવાડિયાઓમાં કોની પાસે જગ્યા છે, અને કોણ વધુ પડતું બંધાયેલું છે.',
            'p1' => 'ટાસ્કને **estimate** આપો - તેમાં કેટલા કલાક લાગવા જોઈએ - તેની Plan પંક્તિના બોક્સમાં, અથવા ટાસ્ક બોર્ડ પરની ટાસ્ક વિન્ડોમાં. પછી દરેક લેન અને Overview અંદાજ સામે નોંધાયેલ સમય બતાવે છે, અને અંદાજ કરતાં વધુ સમય નોંધાય ત્યારે પંક્તિ લાલ થઈ જાય છે.',
            'p2' => 'Projects ની ટોચ પરના **Capacity** પેજમાં પ્રોજેક્ટનું કામ ધરાવતી દરેક વ્યક્તિ માટે એક પંક્તિ અને દરેક અઠવાડિયા માટે એક કૉલમ છે. અઠવાડિયાનો ભાર એટલે તેમનું બાકી રહેલું પ્રોજેક્ટ કામ - દરેક ટાસ્કનો અંદાજ ઓછા પહેલેથી નોંધાયેલ સમય, તેની શરૂઆત (કે આજ) થી નિયત તારીખ સુધીના કામકાજના દિવસોમાં ફેલાવેલ - ઉપરાંત સર્વિસ-ડેસ્ક રોટા પરની તેમની શિફ્ટ, તેઓ અઠવાડિયામાં કામ કરે તે કલાકો સામે. લીલો એટલે જગ્યા છે, એમ્બર એટલે ખેંચાયેલ, લાલ એટલે વધુ પડતું બંધાયેલ. તેની પાછળના ટાસ્ક જોવા પંક્તિ ખોલો.',
            'p3' => 'અઠવાડિયાઓની બાજુમાં દરેક વ્યક્તિ કેટલા ચાલુ પ્રોજેક્ટ્સ પર ખુલ્લું કામ ધરાવે છે (ત્રણ કે વધુ પર ફ્લેગ), તેમની ખુલ્લી ટિકિટ, અને નિયત તારીખ વિનાનું કામ છે. અંદાજ વિનાના ટાસ્ક ગણાય છે પણ ઉમેરાતા નથી, તેથી પેજ કહે છે કે કેટલા છે - અજ્ઞાત કામ જોખમ છે, શૂન્ય નથી. **Projects - Settings - Health** અઠવાડિયાના કલાકો (37.5), અઠવાડિયું ક્યારે એમ્બર થાય (85%), કેટલા પ્રોજેક્ટ્સ એટલે ઘણા, કયા દિવસો કામકાજના છે, અને રોટા શિફ્ટ ગણાય કે નહીં તે સેટ કરે છે (ફક્ત ઓન-કૉલ રોટા માટે તેને બંધ કરો).',
        ],
        'methods' => [
            'nav' => 'કામ કરવાની રીતો',
            'title' => 'Simple, Staged અને Agile',
            'intro' => 'એક પ્રોજેક્ટ, જોવાની ત્રણ રીતો.',
            'p1' => 'તમે પ્રોજેક્ટ કેવી રીતે ચલાવો છો તે નક્કી કરે છે કે તેના ટાઇમ બોક્સને શું કહેવાય અને તે કેવી રીતે વર્તે. અંદરથી, દરેક પ્રોજેક્ટ એક જ રીતે બનેલો છે, અને તેથી જ મન બદલવું સલામત છે.',
            'p2' => 'વચ્ચે રીત બદલવાથી કંઈ ગુમાવાતું નથી. પૂર્ણ થયેલા ફેઝ જે નામ હેઠળ ચલાવાયા તે નામ રાખે છે, ખુલ્લા નવી રીતનું નામ લે છે, અને ફેરફાર પ્રોજેક્ટના ઇતિહાસમાં લખાય છે. જો નવી રીત એક સમયે ફક્ત એક ટાઇમ બોક્સને પ્રગતિમાં રહેવા દે, તો સૌથી પહેલું પ્રગતિમાં રહે છે અને બાકીના પાછા આયોજિત થઈ જાય છે.',
            'simple_d' => 'ફેઝ અને ટાસ્ક. કોઈપણ સંખ્યામાં ફેઝ એકસાથે પ્રગતિમાં હોઈ શકે.',
            'staged_d' => 'તબક્કા જે તમે એક પછી એક પૂર્ણ કરો છો, આગલો શરૂ કરતાં પહેલાં, PRINCE2 ની શૈલીમાં - બોર્ડને રિપોર્ટ કરતા પ્રોજેક્ટ્સ માટે.',
            'agile_d' => 'સ્પ્રિન્ટ, એક સમયે એક - જે કામ તમે શીખતાં શીખતાં બદલાય તેના માટે.',
        ],
        'tools' => [
            'nav' => 'ટૂલ્સ',
            'title' => 'પ્રોજેક્ટના ટૂલ્સ, અને તેમને અનુકૂળ કરવા',
            'intro' => 'પ્રોજેક્ટ ચલાવવાની દરેક રીત પોતાનો સેટ ચાલુ કરે છે.',
            'p1' => 'પ્રોજેક્ટ આઠ ટૂલ વાપરી શકે છે, દરેક પોતાના ટૅબ પર: People, Scope, RACI, RAID, Gates, Budget, Change control અને Benefits. તે કેવી રીતે ચલાવાય છે તે નક્કી કરે છે કે શરૂઆતમાં કયા ચાલુ હોય:',
            'p2' => 'પ્રોજેક્ટને અનુકૂળ કરવા, તેને **Edit** કરો અને **Tools** હેઠળ ટૂલ્સ ટિક કે અન-ટિક કરો (આ વિભાગ સંપાદન વખતે દેખાય છે, બનાવતી વખતે નહીં). ટૂલ બંધ કરવાથી ફક્ત તેનું ટૅબ છુપાય છે: તેમાંનું કંઈ કાઢી નંખાતું નથી, અને તેને પાછું ચાલુ કરવાથી બધું પાછું આવે છે. એ જ ડાયલોગમાં પ્રોજેક્ટ ચલાવવાની રીત બદલવાથી ટૂલ્સ નવી રીતના પોતાના સેટ પર પાછા જાય છે.',
            'p3' => 'Overview પરનું **Toolbox** પ્રોજેક્ટ હજી વાપરતો નથી તેવા ટૂલ્સ યાદી કરે છે - દરેક શેના માટે છે અને તમને ક્યારે જોઈએ - જેથી Simple પ્રોજેક્ટ તેના ટૂલ્સ જરૂર પ્રમાણે વધારી શકે. પ્રોજેક્ટ પોતે જે સૂચવે તે પહેલાં આવે છે, **Suggested** ચિહ્નિત, કારણ સાથે: ત્રણ કે વધુ તબક્કા Gates સૂચવે છે, પહેલેથી ખસેલી લક્ષ્ય તારીખ Change control સૂચવે છે, મોડો પડેલો ટાસ્ક RAID સૂચવે છે. **Add** ટૂલ ચાલુ કરે છે, બરાબર Edit ની જેમ (RACI ઉમેરવાથી People અને Scope પણ ઉમેરાય છે, કારણ કે મેટ્રિક્સ તેમાંથી બને છે). **Hide** તેને તમારા બ્રાઉઝરમાં તે પ્રોજેક્ટ માટે છુપાવે છે. ફક્ત પ્રોજેક્ટ બદલી શકે તેવા લોકો તેને જુએ છે, અને પ્રોજેક્ટ બંધ થયા પછી નહીં. **Projects - Settings - General - Toolbox on the Overview** તેને બધા માટે બંધ કરે છે.',
        ],
        'people' => [
            'nav' => 'લોકો',
            'title' => 'લોકો અને ભૂમિકાઓ',
            'intro' => 'પ્રોજેક્ટમાં કોણ છે, અને દરેક કયો ભાગ ભજવે છે.',
            'p2' => 'ભૂમિકાઓ **Projects - Settings - Roles** માંથી આવે છે, જે PRINCE2-શૈલીની ભૂમિકાઓથી શરૂ થાય છે (Executive, Senior User, Senior Supplier, Project Manager, Team Manager, Project Assurance અને Project Support) ઉપરાંત Team member અને Stakeholder.',
            'p4' => '**Who can see it** (પ્રોજેક્ટના ફોર્મ પર): **Everyone with Projects**, અથવા **Members only** - ફક્ત તેના પ્રોજેક્ટ મેનેજર, જેણે તે બનાવ્યો, તેના સભ્યો (સીધા કે ટીમ દ્વારા) અને Projects મેનેજ કરતા લોકો. HR, સુરક્ષા કે ગોપનીય કામ માટે. બીજા બધા માટે members-only પ્રોજેક્ટ અસ્તિત્વમાં જ નથી: પોર્ટફોલિયો, શોધ, People, Watchtower, Warbot કે API માં નહીં, અને તેની તારીખો શેર્ડ Calendar પર દેખાતી નથી. Capacity હજી પણ તેના ટાસ્ક ગણે છે, "A members-only project" તરીકે. જેને તમે મંજૂરી કે સાઇન-ઑફ માટે કહો તે ખોલવા માટે સભ્ય હોવો જોઈએ. નવા પ્રોજેક્ટ્સ Projects -> Settings -> General કહે તે રીતે શરૂ થાય છે.',
            'p5' => '**Who needs to know?** - સ્ટેકહોલ્ડર મેપ. સભ્ય પર **Place** તેમની **power** (તેઓ પ્રોજેક્ટને કેટલી અસર કરી શકે) અને **interest** (પ્રોજેક્ટ તેમને કેટલી અસર કરે), 1 થી 5, તેઓ ક્યાં ઊભા છે (champion, supporter, neutral, sceptic કે blocker) અને તેમને કેવી રીતે માહિતગાર રાખવામાં આવે છે તે સેટ કરે છે. મેપ દરેકને ક્વાડ્રન્ટમાં મૂકે છે - manage closely, keep satisfied, keep informed, monitor (3 અને ઉપર ઊંચું ગણાય) - અને તેની નીચેનો **communications plan** મૂકેલા દરેકને, સૌથી મહત્વના પહેલા, યાદી કરે છે. તેમને મૂકવા માટે બોર્ડ, સ્પોન્સર્સ અને અસરગ્રસ્ત લોકોને સભ્યો તરીકે ઉમેરો (People મોડ્યુલના People સહિત).',
        ],
        'scope' => [
            'nav' => 'Scope',
            'title' => 'Scope અને MoSCoW',
            'intro' => 'પ્રોજેક્ટ શું પહોંચાડે છે, પ્રાથમિકતા પ્રમાણે ગોઠવેલ.',
            'p1' => 'Scope ટૅબ પ્રોજેક્ટના ડિલિવરેબલ્સ અને જરૂરિયાતોનું પાંચ કૉલમનું બોર્ડ છે: Must, Should, Could, Won\'t (આ વખતે) અને Not prioritised. ત્યાં એક ઉમેરવા કૉલમના તળિયે બોક્સમાં ટાઇપ કરો, અને તેની પ્રાથમિકતા બદલવા કાર્ડને બીજી કૉલમ પર ખેંચો - ફેરફાર ઇતિહાસમાં લખાય છે.',
            'p2' => 'કાર્ડ ખોલવા તેના પર ક્લિક કરો. તેના શીર્ષક અને પ્રાથમિકતા ઉપરાંત તેમાં સ્થિતિ (Proposed, Agreed, In progress, Accepted કે Dropped), તે જે ફેઝનું છે, વર્ણન, અને **Done when...** - તે પહોંચાડાયું છે તે તમને કેવી રીતે ખબર પડશે. ડિલિવરેબલ કાઢી નાખવાથી RACI મેટ્રિક્સમાં તેની પંક્તિ પણ કાઢી નંખાય છે.',
        ],
        'raci' => [
            'nav' => 'RACI',
            'title' => 'કોણ શું કરે છે: RACI',
            'intro' => 'ઉપર લોકો, બાજુમાં ડિલિવરેબલ્સ.',
            'p1' => 'RACI ટૅબ પ્રોજેક્ટના લોકો (કૉલમ) અને તેના ડિલિવરેબલ્સ (પંક્તિઓ) ની ગ્રિડ છે, તેથી તેને બંને જોઈએ: પહેલાં People ટૅબ પર લોકો અને Scope ટૅબ પર ડિલિવરેબલ્સ ઉમેરો. Dropped ડિલિવરેબલ્સ બાકાત રખાય છે.',
            'p2' => 'સેલ પર ક્લિક કરવાથી તે R, A, C, I અને પાછું ખાલી એમ ફરે છે. દરેક ડિલિવરેબલ માટે એક વ્યક્તિ accountable હોય છે: બીજી વ્યક્તિ માટે A સેટ કરવાથી પહેલાની Responsible બને છે, કારણ કે તેઓ હજી કામ કરી રહ્યા છે. જેમાં કોઈ accountable ન હોય કે કોઈ responsible ન હોય તેવી પંક્તિ ડ્રાફ્ટ દરમિયાન માન્ય છે, અને ડિલિવરેબલના નામ નીચે ફ્લેગ થાય છે.',
        ],
        'raid' => [
            'nav' => 'RAID',
            'title' => 'RAID લોગ અને હીટ મેપ',
            'intro' => 'શું ખોટું થઈ શકે, તમે શું માની રહ્યા છો, શું ખોટું થયું છે, તમે શેની રાહ જુઓ છો અને તમે શું નક્કી કર્યું.',
            'p1' => 'RAID ટૅબ છ પ્રકારની એન્ટ્રી લોગ કરે છે: risks, assumptions, issues, dependencies, decisions અને lessons. દરેકમાં શીર્ષક, વિગત, માલિક, સમીક્ષા-તારીખ અને સ્થિતિ, Open કે Closed, હોય છે. ઉપરના બટનો પ્રકાર પ્રમાણે ફિલ્ટર કરે છે અને દરેકના કેટલા ખુલ્લા છે તે બતાવે છે; **Show closed** બંધ એન્ટ્રીઓને યાદીમાં પાછી લાવે છે. એન્ટ્રી લોગ કરવી, બંધ કરવી, ફરી ખોલવી અને કાઢી નાખવી બધું ઇતિહાસમાં લખાય છે.',
            'p2' => 'risk ની એક probability અને એક impact હોય છે, દરેક પાંચ પગથિયાંના માપ પર, અને probability ગુણ્યા impact નો **score**, 1 થી 25. તેનો response (Avoid, Reduce, Transfer, Accept કે Share) અને તે કેવી રીતે સંભાળાશે તેની યોજના પણ હોઈ શકે. issue ની impact હોય છે અને તેને ટિકિટ સાથે લિંક કરી શકાય છે, જો તમે ટિકિટ ખોલી શકો અને તે પ્રોજેક્ટની કંપનીની હોય.',
            'p3' => 'હીટ મેપ, **What could go wrong?**, જેમાં probability અને impact બંને હોય તેવા દરેક ખુલ્લા risk ને પાંચ-બાય-પાંચ ગ્રિડ પર મૂકે છે, score પ્રમાણે લીલાથી લાલ સુધી શેડ કરેલ. ફક્ત તે risk ની યાદી જોવા ચોરસ પર ક્લિક કરો; સાફ કરવા ફરી ક્લિક કરો, અથવા **Show all**. બે માપ પરના શબ્દો **Projects - Settings - RAID** માંથી આવે છે.',
            'p5' => '**dependency** એટલે પ્રોજેક્ટને તેની બહારથી જોઈતું કંઈક - મકાનમાલિક ફિટ-આઉટ પૂરું કરે, સપ્લાયર ડિલિવર કરે, બીજી ટીમ. તેની તારીખ એટલે ક્યાં સુધીમાં જોઈએ; તે આવે ત્યારે બંધ કરો. **decision** લેવાય તે પહેલાં લોગ થાય છે, ક્યાં સુધીમાં લેવાનો છે તે તારીખ સાથે, અને લેવાય ત્યારે બંધ થાય છે, **Decided by** (કોઈપણ નામ - સ્પોન્સર, બોર્ડ), **Decided on** અને **Why** સાથે. તેમને ડિસિઝન લોગ તરીકે જોવા **Decisions** પસંદ કરો. તારીખ પછી પણ ખુલ્લી dependency કે decision પ્રોજેક્ટને એમ્બર બનાવે છે.',
            'p6' => 'સાચવેલી એન્ટ્રી ખોલીને તેને **Escalate** કરો - જ્યારે પ્રોજેક્ટ મેનેજરથી ઉપરની કોઈ વ્યક્તિની જરૂર હોય - શું જોઈએ છે તે કહેતી એક લીટી સાથે. તે Overview પર, RAID ટૅબ અને પોર્ટફોલિયો કાર્ડ પર ચિહ્નિત થઈને દેખાય છે, જ્યાં સુધી તે **De-escalated** કે બંધ ન થાય; પ્રોજેક્ટ મેનેજરને જણાવવામાં આવે છે, અને વર્કફ્લો સ્પોન્સરને જણાવી શકે છે. **Follow-up actions** એન્ટ્રીમાંથી બનેલા પ્રોજેક્ટ પરના ટાસ્ક છે - નિર્ણય પછી શું સંમત થયું, risk નું નિવારણ - કેટલા પૂર્ણ થયા તે લોગ પર બતાવેલ.',
            'p4' => 'સાચવેલ **lesson** ખોલો અને તેને ડ્રાફ્ટ Knowledge લેખમાં ફેરવવા **Knowledge** દબાવો: તેની વિગત લેખ બને છે, પ્રોજેક્ટની લિંક સાથે, અને તે Connections ટૅબ પર લિંક થાય છે. તેને Knowledge માં વાંચો, પછી પ્રકાશિત કરો. પહેલેથી હોય તેવી ટિકિટ લિંક કરવાને બદલે નવી ટિકિટ ઊભી કરવા સાચવેલ **issue** ખોલો અને **Raise** દબાવો: તમે વિનંતી કરનાર છો, તે issue ના માલિક (અથવા તમને) જાય છે, તે પ્રોજેક્ટની કંપનીની હોય છે, અને issue અને પ્રોજેક્ટ બંને તેની સાથે લિંક થાય છે. દરેક એન્ટ્રી દીઠ એક જ વાર થાય છે, અને પ્રોજેક્ટ બદલવાની પરવાનગી ઉપરાંત Knowledge કે Tickets નો ઍક્સેસ જોઈએ.',
            'p7' => '**Export** (Show closed ની બાજુમાં) આખો લોગ - દરેક પ્રકાર, ખુલ્લો અને બંધ - Excel વર્કબુક કે CSV ફાઇલ તરીકે ડાઉનલોડ કરે છે, માલિકો, સ્કોર, પ્રતિભાવો, નિર્ણયો અને ફોલો-અપ કાર્યવાહી સાથે.',
        ],
        'gates' => [
            'nav' => 'ગેટ',
            'title' => 'ગેટ, ટોલરન્સ અને અપવાદો',
            'intro' => 'PRINCE2 શૈલીમાં, તબક્કાવાર પ્રોજેક્ટ જેને જવાબદાર હોય છે તે નિયંત્રણો.',
            'p1' => 'ગેટ ટેબમાં ત્રણ બાબતો છે. **બિઝનેસ કેસ** જણાવે છે કે પ્રોજેક્ટ શા માટે કરવા જેવો છે - લાભો, ખર્ચ અને જોખમો - અને દરેક ગેટ પર તેની સમીક્ષા થવી જોઈએ. **ટોલરન્સ** જણાવે છે કે નિર્ણયની જરૂર પડે તે પહેલાં પ્રોજેક્ટ કેટલો આગળ-પાછળ થઈ શકે. **તબક્કા ગેટ** દરેક તબક્કાના અંતે નિર્ણય નોંધે છે.',
            'p2' => 'બે ટોલરન્સ છે, અને એકને ખાલી છોડવાથી તે બંધ થઈ જાય છે. **મંજૂર મોડા દિવસો** ત્યારે વટાવાય છે જ્યારે લક્ષ્ય સમાપ્તિ અથવા ચાલુ તબક્કાની અંતિમ તારીખ એટલા દિવસ કરતાં વધુ ભૂતકાળમાં હોય અને કામ હજુ ખુલ્લું હોય. **મંજૂર સર્વોચ્ચ જોખમ સ્કોર** ત્યારે વટાવાય છે જ્યારે RAID લોગમાં કોઈ ખુલ્લું જોખમ તેનાથી વધુ સ્કોર કરે.',
            'p3' => 'ટોલરન્સ વટાવવાથી પ્રોજેક્ટ **અપવાદ** બને છે. તે ચાલે ત્યાં સુધી ગણતરીથી નક્કી થયેલી હેલ્થ Off track રહે છે, ઝાંખી અને ગેટ ટેબ પર **ટોલરન્સ વટાવાયું** બેનર દરેકનું નામ આપે છે, અને પોર્ટફોલિયો પરના પ્રોજેક્ટ કાર્ડ પર **અપવાદ** ચિપ દેખાય છે. અપવાદ પ્રોજેક્ટ દેખાડાય ત્યારે દર વખતે ગણાય છે, ક્યારેય સંગ્રહાતા નથી, તેથી પ્રોજેક્ટ ફરી ટોલરન્સમાં આવે એટલે તે જાતે દૂર થઈ જાય છે. તે ફક્ત ચાલુ પ્રોજેક્ટને લાગુ પડે છે જેમાં ગેટ ટૂલ ચાલુ હોય, અને હાથથી સેટ કરેલી હેલ્થ જેવી સેટ કરી હોય તેવી જ રહે છે.',
            'p4' => 'ચાલુ અથવા પૂર્ણ થયેલા તબક્કા પર **નિર્ણય લો** દબાવો (આયોજિત તબક્કામાં બટન નથી), નિર્ણય પસંદ કરો અને નોંધ ઉમેરો. નિર્ણય, કોણે લીધો અને ક્યારે - તે તબક્કા પર રહે છે અને ઇતિહાસમાં લખાય છે. પહેલેથી પૂર્ણ થયેલા તબક્કા પર નોંધાયેલ Go ફક્ત નિર્ણય નોંધે છે: તે બીજો તબક્કો શરૂ કરતો નથી.',
            'p5' => 'નિર્ણય પહેલાં, ગેટ કનેક્શન્સ ટેબ પર લિંક કરેલા **ચેન્જ** તપાસે છે. હજુ ખુલ્લા અને મંજૂર ન થયેલા - મંજૂરીની રાહ જોતા, અથવા કોઈએ સબમિટ ન કરેલા ડ્રાફ્ટ - ગેટ ડાયલોગમાં તેમની સ્થિતિ અને આયોજિત શરૂઆત સાથે દર્શાવાય છે, અને ચાલુ તબક્કા પર કેટલા છે તે કહેતી ચિપ દેખાય છે. આ ચેતવણી છે, અવરોધ નથી: નિર્ણય હજુ તમારો જ છે. તમે ચેન્જ ખોલી શકો તો જ તમને આ દેખાય છે.',
            'p6' => 'દરેક ગેટમાં Go પહેલાં શું સાચું હોવું જોઈએ તેની **ચેકલિસ્ટ** હોઈ શકે: ટિક કરવા માટે **ચેક**; **દસ્તાવેજ** - પ્રોજેક્ટની **દસ્તાવેજો** ટેબ પરની કોઈ ફાઇલ પસંદ કરીને પૂર્ણ કરાય છે (બેકઆઉટ પ્લાન, ટેસ્ટ રિપોર્ટ); નામાંકિત વ્યક્તિ દ્વારા **સાઇન-ઓફ**, જેને બેલ પર જાણ કરાય છે અને જે એકમાત્ર તે સહી કરી શકે છે; અથવા લિંક કરેલ **ચેન્જ** જે ચેન્જમાં મંજૂર થવો જોઈએ. ગેટને **Go-live ગેટ** બનાવો અને તેને શરૂઆતની ચેકલિસ્ટ મળે છે - યુઝર એક્સેપ્ટન્સ ટેસ્ટિંગ સાઇન-ઓફ, બેકઆઉટ પ્લાન, ચેન્જ મંજૂર, સપોર્ટ હેન્ડઓવર સંમત - જેને રાખો, બદલો કે તેમાં ઉમેરો. દરેક આઇટમ પૂર્ણ ન થાય ત્યાં સુધી Go નકારાય છે (Stop ક્યારેય નહીં); Projects - Settings - General તેને બદલે ચેતવણી બનાવી શકે છે, અને ત્યારે હજુ ખુલ્લું શું હતું તે ગેટની નોંધમાં લખાય છે.',
            'go_d' => 'તબક્કો બંધ કરે છે અને આગળનો આયોજિત તબક્કો શરૂ કરે છે.',
            'go_with_conditions_d' => 'Go જેવું જ, નોંધમાં શરતો લખેલી સાથે - તે જરૂરી છે.',
            'stop_d' => 'નોંધે છે કે પ્રોજેક્ટ આયોજન પ્રમાણે આગળ ચાલવો ન જોઈએ. તે કોઈ તબક્કો બદલતું નથી: આગળ શું થાય તે પ્રોજેક્ટ ચલાવતા લોકો નક્કી કરશે.',
        ],
        'templates' => [
            'nav' => 'ટેમ્પ્લેટ',
            'title' => 'ટેમ્પ્લેટથી શરૂ કરો',
            'intro' => 'પહેલેથી આયોજિત થયેલો પ્રોજેક્ટ.',
            'p1' => 'પ્રોજેક્ટ બનાવતી વખતે, **શરૂ કરો** ટેમ્પ્લેટ આપે છે: ઓફિસ ખસેડવી, લેપટોપ રિફ્રેશ, મેઈલ માઇગ્રેશન, Windows 11 રોલઆઉટ અને સર્વિસ ડેસ્ક સુધારણા બિલ્ટ-ઇન આવે છે. એક પસંદ કરો અને પ્રોજેક્ટ તેના તબક્કા, ટાસ્ક, સ્કોપ, જોખમો અને ટોલરન્સ પહેલેથી મૂકેલા સાથે બને છે, અને તેની ચલાવવાની રીત, રંગ, આઇકન અને ધ્યેય તમારા માટે ભરાઈ જાય છે. ફોર્મમાં તમે જે લખો તે ટેમ્પ્લેટ કરતાં ઉપર ગણાય છે.',
            'p2' => 'ટેમ્પ્લેટ તારીખોને શરૂઆતથી દિવસો તરીકે રાખે છે, તેથી દરેક તારીખ તમે આપેલી **શરૂઆતની તારીખ**થી ગણાય છે - ખાલી રાખો તો આજથી - અને તમે એક સેટ ન કરો ત્યાં સુધી લક્ષ્ય સમાપ્તિ તેને અનુસરે છે. ટાસ્ક સામાન્ય ટાસ્ક છે, કોઈને સોંપાયા નથી, અને કંઈ ટિક થયેલું નથી. નામથી સ્થિતિ કે સ્થાન માંગતો એસેટ ટાર્ગેટ (દા.ત. "Retired") ફક્ત ત્યારે જ ઉમેરાય છે જ્યારે તે નામ તમારા ઇન્સ્ટોલ પર અસ્તિત્વમાં હોય.',
            'p3' => 'તમારું પોતાનું બનાવવા માટે, સારી રીતે પાર પડેલો પ્રોજેક્ટ ખોલો અને **ટેમ્પ્લેટ** દબાવો. શું રાખવું તે પસંદ કરો: તબક્કા અને ટાસ્ક, સ્કોપ, જોખમો અને ધારણાઓ, ટોલરન્સ (મંજૂર ઓવરસ્પેન્ડ સહિત) અને એસેટ ટાર્ગેટ. ટેમ્પ્લેટ બદલવા માટે, તેમાંથી પ્રોજેક્ટ શરૂ કરો, પ્રોજેક્ટ બદલો, **ટેમ્પ્લેટ** દબાવો અને **તમારા ટેમ્પ્લેટમાંથી એક બદલો** પસંદ કરો - બિલ્ટ-ઇન ટેમ્પ્લેટની નકલ આ રીતે થઈ શકે છે, ક્યારેય ઓવરરાઇટ નહીં. લોકો, કંપની, લિંક અને પ્રગતિ ક્યારેય રખાતા નથી, તેથી એક ટેમ્પ્લેટ કોઈપણ કંપની માટે કામ કરે છે. **Projects - Settings - Templates** બધાની યાદી આપે છે: ક્યારેય ન વાપરતા બિલ્ટ-ઇનને છુપાવો, અને તમારા પોતાનાનું નામ બદલો, બંધ કરો અથવા કાઢી નાખો. ટેમ્પ્લેટ સાચવવા અને સંભાળવા માટે ટેમ્પ્લેટ પરવાનગી જોઈએ; પ્રોજેક્ટ બનાવી શકે તે કોઈપણ તેમાંથી શરૂ કરી શકે છે.',
            'p4' => '3.3.0 થી ટેમ્પ્લેટ પ્લાનની **નિર્ભરતાઓ**, દરેક તબક્કાની **ગેટ ચેકલિસ્ટ** (અને તે go-live ગેટ છે કે નહીં - હજુ સાઇન-ઓફ માટે કોઈનું નામ નથી) અને, જો તમે રાખો તો, ટાર્ગેટ સાથેના **લાભો** (બેઝલાઇન ક્યારેય નહીં - તે નવા પ્રોજેક્ટ પર માપાય છે) પણ રાખે છે. પાંચ બિલ્ટ-ઇન ટેમ્પ્લેટમાં ત્રણેય આવે છે.',
        ],
        'targets' => [
            'nav' => 'એસેટ ટાર્ગેટ',
            'title' => 'એસેટ ટાર્ગેટ: એસેટ્સમાંથી સીધી પ્રગતિ',
            'intro' => '"480 માંથી 312 લેપટોપ બદલાયા", એસેટ્સ પરથી જ ગણાયેલા.',
            'p1' => 'એસેટ ટાર્ગેટ પ્રોજેક્ટની ઝાંખી પર હોય છે અને એસેટ્સમાં કંઈક ગણે છે: જે Latitude 5430 રિટાયર થયા છે, જે Windows મશીન હવે Windows 11 પર છે, જે લેપટોપમાં BitLocker ચાલુ છે. પેજ ખુલે ત્યારે દર વખતે ગણતરી થાય છે, તેથી કોઈ એસેટ બદલે કે તરત પ્રોજેક્ટ આગળ વધે છે - કોઈએ કંઈ ટિક કરવાનું યાદ રાખવું પડતું નથી. દરેક ટાર્ગેટ તેની પ્રગતિની રેખા દોરે છે, સેટ કર્યાના દિવસથી દિવસે એક બિંદુ.',
            'p2' => '**કઈ એસેટ્સ** પસંદ કરો: કાં તો પ્રકાર અને/અથવા કોઈ ટેક્સ્ટ ધરાવતા ફીલ્ડ સાથે **મેળ ખાતી** (મોડેલમાં 5430 હોય), અથવા કનેક્શન્સ ટેબ પર **આ પ્રોજેક્ટ સાથે લિંક કરેલી**. પછી **ક્યારે એક પૂર્ણ ગણાય** તે પસંદ કરો: સ્થિતિ, સ્થાન, ઓપરેટિંગ સિસ્ટમ, ફીચર રિલીઝ, મોડેલ, ઉત્પાદક, BitLocker અથવા TPM વર્ઝન. તમે ટાઇપ કરો તેમ ડાયલોગ કેટલી એસેટ્સ મેળ ખાય છે અને કેટલી પૂર્ણ છે તે બતાવે છે. ટાર્ગેટ ફક્ત પ્રોજેક્ટની પોતાની કંપનીની એસેટ્સ ગણે છે.',
            'p3' => 'દરેક ટાર્ગેટની એક તારીખ હોય છે - તેની પોતાની, અથવા પ્રોજેક્ટની લક્ષ્ય સમાપ્તિ તારીખ. તારીખ વીતી ગઈ હોય અને પૂર્ણ ન થયો હોય તેવો ટાર્ગેટ પ્રોજેક્ટને લાલ કરે છે; સેટ કર્યાના દિવસથી તેની તારીખ સુધીની સીધી રેખા કરતાં 25 પોઇન્ટથી વધુ પાછળ હોય તેવો ટાર્ગેટ તેને કેસરી કરે છે. **હજુ કરવાનું** બાકી રહેલી એસેટ્સની યાદી આપે છે, દરેક એસેટની લિંક. ટાર્ગેટ સેટ કરવા અને તેની પાછળ કઈ એસેટ્સ છે તે જોવા માટે એસેટ્સનો એક્સેસ તેમજ પ્રોજેક્ટ બદલવાની પરવાનગી જોઈએ; નિયમ બદલવાથી તેની રેખા ફરી શરૂ થાય છે.',
        ],
        'health' => [
            'nav' => 'હેલ્થ',
            'title' => 'હેલ્થ કેવી રીતે ગણાય છે',
            'intro' => 'પ્લાન પરથી, કોઈના મૂડ પરથી નહીં.',
            'p1' => 'કોઈ તેને હાથથી સેટ ન કરે ત્યાં સુધી, ચાલુ પ્રોજેક્ટની હેલ્થ દેખાડાય ત્યારે દર વખતે તેના ટાસ્ક અને લક્ષ્ય તારીખ પરથી ગણાય છે. નીચેના આંકડા ડિફોલ્ટ છે; તે **Projects - Settings - Health** માં બદલી શકાય છે.',
            'green_d' => 'નીચેનું કંઈ લાગુ પડતું નથી.',
            'amber_d' => 'ઓછામાં ઓછો એક ખુલ્લો ટાસ્ક મોડો છે, માઇલસ્ટોન ચૂકી જવાયો છે અથવા નિર્ભરતા કે નિર્ણય તેની તારીખ વટાવી ગયો છે (આ બેમાંથી દરેકને લાલ અથવા કંઈ નહીં પર સેટ કરી શકાય છે, Projects - Settings - Health માં), લક્ષ્ય તારીખ નજીક છે અને કામ ઓછું પૂર્ણ થયું છે - ડિફોલ્ટ રૂપે 14 દિવસની અંદર ત્રણ ચતુર્થાંશથી ઓછું પૂર્ણ - અથવા લિંક કરેલી ટિકિટમાં ઉછાળો: ડિફોલ્ટ રૂપે છેલ્લા 7 દિવસમાં 5 કે વધુ ઊભી થઈ, જેનો અર્થ go-live પછી સામાન્ય રીતે કંઈક સુધારવાની જરૂર હોય છે.',
            'red_d' => 'લક્ષ્ય તારીખ વીતી ગઈ છે અને કામ હજુ ખુલ્લું છે, ખુલ્લા કામનો બહુ મોટો ભાગ મોડો છે - ડિફોલ્ટ રૂપે ચોથા ભાગ કે વધુ - અથવા પ્રોજેક્ટ કોઈ ટોલરન્સ વટાવી ગયો છે (ગેટ જુઓ). એસેટ ટાર્ગેટ પણ ગણાય છે: તારીખ વટાવી ગયેલો એક પ્રોજેક્ટને લાલ કરે છે, ઘણો પાછળ હોય તેવો એક લીલા પ્રોજેક્ટને કેસરી કરે છે (એસેટ ટાર્ગેટ જુઓ).',
            'p2' => 'જાતે સેટ કરવા માટે, પ્રોજેક્ટ સંપાદિત કરો અને હેલ્થ પસંદ કરો; શા માટે તે કહેતી એક લીટી ઉમેરો. પાછું સોંપવા માટે **મારા માટે ગણો** પસંદ કરો. બંધ અને રદ કરેલા પ્રોજેક્ટમાં હેલ્થ હોતી નથી.',
        ],
        'tasks' => [
            'nav' => 'ટાસ્ક',
            'title' => 'પ્રોજેક્ટ ટાસ્ક સામાન્ય ટાસ્ક છે',
            'intro' => 'દરેક વ્યક્તિ માટે કામની એક યાદી, બે નહીં.',
            'p1' => 'પ્રોજેક્ટમાં ઉમેરાયેલો ટાસ્ક સામાન્ય ટાસ્ક છે: તે ટાસ્ક બોર્ડ પર દેખાય છે, તેને સોંપી શકાય, શેડ્યૂલ કરી શકાય, સમય નોંધી શકાય, તેના પર ટિપ્પણી કરી શકાય અને ઉપકાર્યો તથા ચેકલિસ્ટ આપી શકાય, અને તે સામાન્ય ઈમેઇલ અને સૂચનાઓ મોકલે છે. પ્રગતિ ઉચ્ચ-સ્તરના ટાસ્ક ગણે છે; ઉપકાર્યો તેમના ટાસ્કના છે.',
            'p2' => 'પ્રોજેક્ટ કાઢી નાખવાથી તેના ટાસ્ક ક્યારેય કાઢી નંખાતા નથી. તે ટાસ્ક બોર્ડ પર રહે છે અને ફક્ત પ્રોજેક્ટના ભાગ તરીકે રહેતા નથી. ફેઝ દૂર કરવાનું પણ એમ જ કામ કરે છે: તેના ટાસ્ક પ્રોજેક્ટમાં રહે છે, બસ કોઈ ફેઝમાં નહીં.',
        ],
        'contractors' => [
            'nav' => 'કોન્ટ્રાક્ટર',
            'title' => 'કોન્ટ્રાક્ટરો દ્વારા થતું કામ',
            'intro' => 'જ્યારે બહારની પેઢી પ્રોજેક્ટનો એક ભાગ કરે - કેબલિંગ, ખસેડવું, ઇન્સ્ટોલ.',
            'p1' => 'ટાસ્ક **કોન્ટ્રાક્ટર**ને આપી શકાય: કરારોમાંથી એક સપ્લાયર, અને ઈચ્છો તો ત્યાંની એક વ્યક્તિ. ટાસ્ક બોર્ડ પરની ટાસ્ક વિન્ડોમાં **કોન્ટ્રાક્ટર** અને **ત્યાં સંપર્ક** હેઠળ તેમને પસંદ કરો. **સોંપાયેલ** એ અહીંની તે વ્યક્તિ રહે છે જે ટાસ્કની માલિક છે અને પેઢી પાસે પીછો કરે છે - તેથી કોન્ટ્રાક્ટર ટાસ્કમાં બંને હોય છે. સપ્લાયર પસંદ કરવા માટે કરારોનો એક્સેસ જોઈએ; ટાસ્ક જોઈ શકે તે કોઈપણ જુએ છે કે તે કોની સાથે છે.',
            'p2' => 'કોન્ટ્રાક્ટર ટાસ્ક પ્લાન, ટાઇમલાઇન અને ટાસ્ક બોર્ડ પર પેઢીનું નામ ધરાવે છે, જ્યાં **કોન્ટ્રાક્ટર** ફિલ્ટર એક પેઢીનું કામ, બધું કોન્ટ્રાક્ટર કામ, અથવા કંઈ નહીં બતાવે છે. **લોકો** ટેબ પર, **કોઈને ઉમેરો - કોન્ટ્રાક્ટર** પેઢીને, અથવા ત્યાંની એક વ્યક્તિને, ભૂમિકા સાથે પ્રોજેક્ટ પર મૂકે છે, જેથી તેઓ RACI મેટ્રિક્સ અને સ્ટેકહોલ્ડર નકશા પર હોઈ શકે. લોકોમાં સપ્લાયરનું પેજ તેમની સાથેના દરેક ટાસ્કની યાદી આપે છે.',
            'p3' => 'કોન્ટ્રાક્ટરનું કામ **ક્ષમતા** પર કોઈના લોડમાં નથી - તે નીચે યાદીબદ્ધ છે, દરેક પેઢી માટે એક લીટી, તેના ખુલ્લા ટાસ્ક, બાકી કલાકો અને કેટલા મોડા છે તે સાથે. મોડા ટાસ્કનું ડાયજેસ્ટ, AI બ્રીફિંગ અને **AIને પૂછો** બધા કહે છે કે કયું મોડું કામ કોન્ટ્રાક્ટર પાસે છે, અને AIને પૂછો ટાસ્ક કોઈને આપવાનું સૂચવી શકે છે.',
            'p4' => '**કોન્ટ્રાક્ટરને ઈમેઇલ** (Projects - Settings - General) શરૂઆતમાં બંધ છે: કોન્ટ્રાક્ટરનું કામ અહીં ટ્રૅક થાય છે અને તમે જાતે પીછો કરો છો. તેને ચાલુ કરો અને ટાસ્ક આપતી વખતે, નિયત તારીખના બે દિવસ પહેલાં, અને ચૂકી જવાય તો એક વાર પેઢીની વ્યક્તિને ઈમેઇલ થાય છે - તમારા આઉટગોઇંગ મેઈલબોક્સમાંથી, ટાસ્ક, તારીખો અને અહીં કોને જવાબ આપવો તે સાથે. ફક્ત ઈમેઇલ સરનામું ધરાવતી વ્યક્તિ સાથેના ટાસ્ક મોકલાય છે; દરેક ઈમેઇલ મોકલવાના લોગમાં **કોન્ટ્રાક્ટર માટે ટાસ્ક** તરીકે હોય છે.',
        ],
        'connections' => [
            'nav' => 'કનેક્શન્સ',
            'title' => 'પ્રોજેક્ટને બાકી બધા સાથે જોડવો',
            'intro' => 'સાધનો, ચેન્જ, ટિકિટ, કરાર, કન્ફિગરેશન આઇટમ, નોલેજ અને સમસ્યાઓ.',
            'p1' => 'કનેક્શન્સ ટેબ પ્રોજેક્ટને તે જે રેકોર્ડને સ્પર્શે છે તેની સાથે જોડે છે: બદલાતા લેપટોપ, તે જે ચેન્જ ઊભા કરે છે (તે મંજૂર છે કે નહીં સાથે), તેના કારણે થયેલી ટિકિટ, તે જેના પર આધારિત છે તે સપ્લાયર કરાર, CMDB માંની સિસ્ટમ, નોલેજમાંના રનબુક અને જે સમસ્યાઓ ઉકેલવા માટે તે છે. શોધવા માટે પ્રકાર હેઠળના બોક્સમાં ટાઇપ કરો, અને લિંક કરવા માટે પરિણામ પસંદ કરો. ઝાંખી દરેકના કેટલા જોડાયેલા છે તે બતાવે છે.',
            'p2' => 'તમે કોઈ પ્રકારનું મોડ્યુલ ખોલી શકો તો જ તે પ્રકાર દેખાય છે, અને બીજા છેડાનો રેકોર્ડ ખોલી શકો તો જ લિંક દેખાય છે. એકથી વધુ કંપની ધરાવતા ઇન્સ્ટોલ પર, સાધનો, ચેન્જ, ટિકિટ, સમસ્યાઓ અને કન્ફિગરેશન આઇટમ પ્રોજેક્ટની પોતાની કંપનીના હોવા જોઈએ. અનલિંક કરવાથી રેકોર્ડ પોતે ક્યારેય બદલાતો નથી, અને બંને પ્રોજેક્ટના ઇતિહાસમાં લખાય છે.',
            'p3' => 'દરેક રેકોર્ડ તેના પોતાના છેડેથી પણ તેના પ્રોજેક્ટ બતાવે છે. **સમસ્યા**માં **પ્રોજેક્ટ્સ** પેનલ હોય છે જે તે જે પ્રોજેક્ટનો ભાગ છે તેની યાદી હેલ્થ અને પ્રગતિ સાથે આપે છે, અને ત્યાંથી તેને ચાલુ પ્રોજેક્ટ સાથે લિંક કરવા માટે **પ્રોજેક્ટમાં ઉમેરો** - પ્રોજેક્ટની કનેક્શન્સ ટેબ પરની જ લિંક.',
        ],
        'calendar' => [
            'nav' => 'કૅલેન્ડર પર',
            'title' => 'કૅલેન્ડર પર પ્રોજેક્ટ તારીખો',
            'intro' => 'લક્ષ્ય સમાપ્તિ તારીખો, તબક્કાની સમાપ્તિ અને માઇલસ્ટોન, જ્યાં બાકીની ટીમ પહેલેથી જુએ છે.',
            'p1' => 'દરેક પ્રસ્તાવિત અથવા સક્રિય પ્રોજેક્ટ તેની લક્ષ્ય સમાપ્તિ તારીખ શેર્ડ કૅલેન્ડર પર "Project due" તરીકે મૂકે છે, અને જે તબક્કો, ફેઝ કે સ્પ્રિન્ટ બંધ થયો નથી તે પણ તેની સમાપ્તિ તારીખ ત્યાં મૂકે છે, અને દરેક માઇલસ્ટોન પણ તે પહોંચાય ત્યાં સુધી. તે Projects નામની શ્રેણીમાં આખા-દિવસની એન્ટ્રી છે, જેનું નામ કે રંગ તમે કૅલેન્ડર પર બદલી શકો. પ્રોજેક્ટમાં તારીખ બદલો અને કૅલેન્ડર અનુસરે છે; તબક્કો બંધ કરો, અથવા પ્રોજેક્ટ હોલ્ડ પર મૂકો, બંધ કરો કે રદ કરો, તો તેની એન્ટ્રીઓ જતી રહે છે. **Projects - Settings - General** પસંદ કરે છે કે કૅલેન્ડર બધી બતાવે, ફક્ત લક્ષ્ય સમાપ્તિ તારીખો, કે કંઈ નહીં.',
            'p2' => 'એન્ટ્રીઓ Projects દ્વારા લખાય છે, તેથી કૅલેન્ડર પર તેમાંની કોઈમાં કરેલો ફેરફાર કોઈપણ પ્રોજેક્ટ બદલાય ત્યારે આગલી વખતે બદલાઈ જાય છે. તેમના શબ્દો અંગ્રેજીમાં છે, જેમ બીજી આપોઆપ એન્ટ્રીઓ છે. કૅલેન્ડર એન્ટ્રીઓમાં કંપની હોતી નથી, તેથી એકથી વધુ કંપની ધરાવતા ઇન્સ્ટોલ પર કૅલેન્ડર ખોલી શકે તે દરેક વ્યક્તિ દરેક પ્રોજેક્ટની તારીખો જુએ છે.',
        ],
        'alerts' => [
            'nav' => 'એલર્ટ અને વર્કફ્લો',
            'title' => 'એલર્ટ, અને વર્કફ્લોમાં પ્રોજેક્ટ',
            'intro' => 'કંઈક ધ્યાન માંગે ત્યારે પ્રોજેક્ટ મેનેજરને ખબર પડે છે, અને વર્કફ્લો તેના પર કાર્ય કરી શકે છે.',
            'p1' => 'સૂચના બેલ પ્રોજેક્ટના મેનેજરને જણાવે છે જ્યારે તેની હેલ્થ બદલાય (લીલી, કેસરી કે લાલ, ગણતરીથી કે હાથથી સેટ), જ્યારે તે સમય કે જોખમ ટોલરન્સથી આગળ જાય, જ્યારે તબક્કો, ફેઝ કે સ્પ્રિન્ટ 7 દિવસમાં અને ફરી આગલા દિવસે પૂરો થાય, જ્યારે માઇલસ્ટોન 7 દિવસ દૂર હોય, આગલા દિવસે, અને ચૂકી જવાય તો, અને જ્યારે કોઈ ચેન્જ વિનંતી ઊભી કરે, મંજૂર કરે કે નકારે. દરેક એક વાર જણાવાય છે, જ્યારે તે થાય: લાલ રહેતો પ્રોજેક્ટ દર કલાકે વાગતો નથી, અને ભંગ દૂર થઈને પાછો આવે તો તે નવા સમાચાર છે. કોઈને તેમણે પોતે કરેલા ચેન્જ વિશે જણાવાતું નથી. દરેક વ્યક્તિ આ બંધ કરી શકે છે, અથવા તબક્કો બંધ થાય કે માઇલસ્ટોન પહોંચાય ત્યારે બેલ ચાલુ કરી શકે છે, **Preferences - Notifications** માં.',
            'p2' => 'આ જ ક્ષણો **વર્કફ્લો**માં ટ્રિગર છે: પ્રોજેક્ટની હેલ્થ બદલાય, ટોલરન્સ ભંગ થાય, તબક્કો બંધ થાય, તબક્કો જલદી પૂરો થાય, માઇલસ્ટોન આવી રહ્યો હોય, ચૂકાયો હોય કે પહોંચાયો હોય, ચેન્જ વિનંતી ઊભી થાય કે તેનો નિર્ણય થાય, અને પ્રોજેક્ટ બને, અપડેટ થાય કે કાઢી નંખાય. વર્કફ્લો પ્રોજેક્ટ લાલ થાય ત્યારે Teams કે Slack પર પોસ્ટ કરી શકે, ટોલરન્સ ભંગ થાય ત્યારે ટિકિટ ઊભી કરી શકે, કે તબક્કો બંધ થાય ત્યારે બોર્ડને ઈમેઇલ કરી શકે, પ્રોજેક્ટનું નામ, કોડ, હેલ્થ, મેનેજર અને તારીખોનો ઉપયોગ કરીને.',
            'p3' => 'હેલ્થ અને ટોલરન્સ પ્લાન પરથી ગણાય છે, તેથી કોઈકે જોવું પડે. પ્રોજેક્ટ પર કંઈપણ સાચવવાથી તરત જોવાય છે; નહીંતર શેડ્યૂલ્ડ વર્કફ્લો જોબ તે કરે છે (cron/workflow_scheduled.php, કલાકે એક વાર પૂરતું છે), અને શેડ્યૂલ્ડ જોબ વગરના ઇન્સ્ટોલ પર, પોર્ટફોલિયો ખોલવાથી વધુમાં વધુ દર 15 મિનિટે જોવાય છે. રાતોરાત મોડો થતો ટાસ્ક જે પહેલાં આવે તેનાથી નોંધાય છે.',
            'p4' => '**રિમાઇન્ડર.** દરેક પ્રોજેક્ટ મેનેજરને તેમના સક્રિય પ્રોજેક્ટના **મોડા ટાસ્ક**ની યાદી આપતી બેલ મળે છે - સોમવારે સાપ્તાહિક, દૈનિક કે ક્યારેય નહીં (Projects -> Settings -> General, *મોડા ટાસ્ક ડાયજેસ્ટ*). અને જ્યારે પ્રસ્તાવ, ચેન્જ વિનંતી, ગેટ સાઇન-ઓફ કે રિપોર્ટ ડ્રાફ્ટ નિર્ણય માટે **3 દિવસ** રાહ જોઈ ચૂક્યો હોય, ત્યારે નિર્ણય લેનારા લોકોને યાદ અપાય છે - *હજુ તમારા સાઇન-ઓફની રાહ છે* - અને દર 3 દિવસે ફરી (*યાદ અપાવો પછી*; 0 = કોઈ રિમાઇન્ડર નહીં). 45 દિવસથી જૂનું કંઈ યાદ અપાવાતું નથી.',
            'p5' => 'બેલ આ પણ જણાવે છે: કોઈ RAID એન્ટ્રી એસ્કેલેટ કરે ત્યારે પ્રોજેક્ટ મેનેજરને; નવા પ્રસ્તાવ વિશે મંજૂર કરનારાઓને, અને નિર્ણય વિશે જેમણે પ્રસ્તાવ મૂક્યો તેમને; ગેટ પર નામાંકિત વ્યક્તિને જ્યારે તેમના સાઇન-ઓફની જરૂર હોય; લાભના માલિક અને પ્રોજેક્ટ મેનેજરને જ્યારે સમીક્ષા બાકી હોય, બંધ થયા પછી પણ; અને શેડ્યૂલ્ડ રિપોર્ટનો ડ્રાફ્ટ બન્યો હોય ત્યારે પ્રોજેક્ટ મેનેજરને. આમાંની દરેક, મોડા ટાસ્કનું ડાયજેસ્ટ અને રિમાઇન્ડર **વર્કફ્લો**માં પણ ટ્રિગર છે.',
        ],
        'budget' => [
            'nav' => 'બજેટ',
            'title' => 'બજેટ: આયોજિત સામે વાસ્તવિક',
            'intro' => 'પ્રોજેક્ટનો ખર્ચ કેટલો થવાનો હતો, કેટલો થયો, અને બંને વચ્ચે કેટલું અંતર છે.',
            'p1' => 'બજેટ ટેબ (તબક્કાવાર પ્રોજેક્ટ માટે ચાલુ; બીજા માટે ટૂલ્સ હેઠળ ચાલુ કરો) આયોજિત બજેટ, વાસ્તવિક ખર્ચ, શું બાકી છે અને કેટલું વપરાયું છે તે બતાવે છે. તમે જેના પર ખર્ચની અપેક્ષા રાખો છો તે દરેક માટે **બજેટ લાઇન** ઉમેરો - હાર્ડવેર, લાઇસન્સ, સપ્લાયર - શું આયોજિત હતું અને શું ખર્ચાયું તે સાથે. લાઇન કનેક્શન્સ ટેબ પર લિંક કરેલા કરારનું નામ આપી શકે: તેનું વાસ્તવિક ખાલી રાખો તો કરારનું મૂલ્ય વપરાય છે. તે પ્રોજેક્ટની કંપનીનું કોસ્ટ સેન્ટર પણ ધરાવી શકે.',
            'p2' => '**લેબર** એ પ્રોજેક્ટના ટાસ્ક પર નોંધાયેલો સમય છે. Projects - Settings - Budget નક્કી કરે છે કે તે કલાકોમાં બતાવાય, એક કલાકદીઠ દર (જે પ્રોજેક્ટ ઓવરરાઇડ કરી શકે) પર કિંમતાંકિત થાય, કે દરેક વિશ્લેષકના દર પર કિંમતાંકિત થાય. દરેક દર એક તારીખથી લાગુ પડે છે, તેથી નવો દર પહેલેથી નોંધાયેલા સમયની ફરી કિંમત કરતો નથી, અને સેટિંગ બદલવાથી કંઈ ફરી લખાતું નથી - સમય સમય તરીકે સંગ્રહાય છે.',
            'p4' => '**પૈસા ક્યાં જાય છે** દરેક શ્રેણી માટે આયોજિત સામે વાસ્તવિકનો ચાર્ટ બનાવે છે, કિંમત નક્કી થયા પછી લેબર સહિત. **ટેબલ** એ જ આંકડા ટેબલ તરીકે બતાવે છે.',
            'p5' => 'લાઇન **ક્યારે** કહી શકે: પૈસા જવાની આયોજિત તારીખ અને તે ગયાની તારીખ. **સમય સાથે ખર્ચ** તેમને દિવસ-દિવસ ઉમેરે છે - અત્યાર સુધી આયોજિત અને ખર્ચાયેલું - આજથી લક્ષ્ય સમાપ્તિ સુધી ડેશ્ડ **ફોરકાસ્ટ** સાથે, અને માપવા માટે રેખાઓ તરીકે બજેટ, તાજેતરની બેઝલાઇનનું બજેટ અને ઓવરસ્પેન્ડ ટોલરન્સ. **ફોરકાસ્ટ** એ છે જે પ્રોજેક્ટનો હવે અપેક્ષિત ખર્ચ છે: દરેક લાઇનનું પોતાનું ફોરકાસ્ટ (એક ટાઇપ કરો, નહીંતર આયોજિત અને ખર્ચાયેલામાંથી મોટું), વત્તા લેબર - નોંધાયેલ, અને ખુલ્લા ટાસ્કના અંદાજોમાં હજુ આવવાનું, આજના દરે કિંમતાંકિત. વાસ્તવિક વગરની લેબર લાઇન લેબરનો પ્લાન છે, તેથી લેબર ક્યારેય બે વાર ગણાતું નથી. અંદાજો ગણાય કે નહીં, અને **મંજૂર ઓવરસ્પેન્ડ** ખર્ચાયેલું માપે કે ફોરકાસ્ટ - જે વહેલી ચેતવણી આપે છે - તે Projects - Settings - Budget નક્કી કરે છે.',
            'p3' => 'દરેક પ્રોજેક્ટ જે **ચલણ** સાથે બન્યો હોય તે રાખે છે, અને જુદા જુદા ચલણની રકમ ક્યારેય ભેગી ગણાતી નથી: બીજા ચલણનો કરાર તેની લાઇન પર બતાવાય છે પણ ગણાતો નથી. Projects - Settings પ્રોજેક્ટને પસંદ કરવા દે તો, ચલણ બટન પ્રોજેક્ટનું લેબલ બદલે છે - રૂપાંતર કરતું નથી. ગેટ ટેબ પર, **મંજૂર ઓવરસ્પેન્ડ** ખર્ચ ટોલરન્સ સેટ કરે છે: તેનાથી વધુ બજેટ ઓળંગવાથી પ્રોજેક્ટ અપવાદ અને Off track બને છે.',
            'p6' => '**અર્ન્ડ વેલ્યુ** ત્રણ રેખાઓની સરખામણી કરે છે: પ્લાન્ડ વેલ્યુ (બજેટ જેમ ખર્ચાવાનું આયોજિત હતું, લાઇનની આયોજિત તારીખો પરથી), અર્ન્ડ વેલ્યુ (બજેટ ગુણ્યા થયેલા કામનો હિસ્સો - અંદાજિત કલાકો પ્રમાણે, અથવા અંદાજ ન હોય તો ટાસ્ક પ્રમાણે) અને વાસ્તવિક ખર્ચ. **CPI** એટલે અર્ન્ડ વેલ્યુ ભાગ્યા વાસ્તવિક ખર્ચ - 1 થી નીચે, થયેલા કામનો ખર્ચ ધાર્યા કરતાં વધુ થયો છે; **SPI** એટલે અર્ન્ડ વેલ્યુ ભાગ્યા પ્લાન્ડ વેલ્યુ - 1 થી નીચે, પ્લાનથી પાછળ; **એસ્ટિમેટ એટ કમ્પ્લીશન** એટલે બજેટ ભાગ્યા CPI.',
        ],
        'benefits' => [
            'nav' => 'લાભો',
            'title' => 'લાભો: પ્રોજેક્ટ સફળ રહ્યો?',
            'intro' => 'પ્રોજેક્ટ શું સુધારવાનો છે, તે જ્યાંથી શરૂ થયો ત્યાંથી માપેલું - અને બંધ થયા પછી સમીક્ષા, જ્યારે મોટા ભાગના લાભો આવે છે.',
            'p1' => '**લાભો** ટેબ (તબક્કાવાર પ્રોજેક્ટ માટે ચાલુ; બીજા માટે ટૂલ્સ હેઠળ ચાલુ કરો) પ્રોજેક્ટે શું સુધારવું જોઈએ તેની યાદી આપે છે. એક **ઉમેરો**: શું સુધરે છે, તે કેવી રીતે અને કયા એકમમાં માપાય છે, કઈ દિશા સારી છે (ઊંચું કે નીચું), **બેઝલાઇન** (આજે ક્યાં છે), **ટાર્ગેટ** અને તે પહોંચવાની તારીખ, માલિક, અને તેની સમીક્ષા ક્યારે થાય. દરેક લાભ બેઝલાઇન, હમણાં અને ટાર્ગેટ બાજુબાજુમાં બતાવે છે, કેટલું આગળ આવ્યું તે સાથે, અને આમાંથી એક: હજુ માપ્યું નથી, પ્રગતિમાં, સિદ્ધ, અથવા ટાર્ગેટ તારીખ ચૂકી.',
            'p2' => '**નોંધ** માપ ઉમેરે છે - મૂલ્ય અને તે માપ્યાની તારીખ. સૌથી તાજું "હમણાં" છે. સમીક્ષા તારીખે કે તેની નજીક (14 દિવસ વહેલું સુધી) નોંધવું સમીક્ષા ગણાય છે, અને આગલી સમીક્ષા લાભના અંતરાલથી આગળ વધે છે; અંતરાલ 0 હોય તો એક જ વાર સમીક્ષા થાય છે. **ઇતિહાસ** દરેક માપની યાદી આપે છે. જ્યારે લાભ પર નજર રાખવાની જરૂર ન રહે, ત્યારે તેને સંપાદિત કરો અને **આ લાભની સમીક્ષા બંધ કરો** ટિક કરો.',
            'p3' => 'જ્યારે સમીક્ષા તારીખ આવે ત્યારે બેલ લાભના માલિક અને પ્રોજેક્ટ મેનેજરને જણાવે છે (Projects - Settings - General તેને ફક્ત માલિક કરી શકે) - **પ્રોજેક્ટ બંધ થયા પછી પણ**; રદ કરેલા પ્રોજેક્ટની સમીક્ષા થતી નથી. ઝાંખી અને પોર્ટફોલિયો કાર્ડ બાકી સમીક્ષાઓ બતાવે છે, અને રિપોર્ટ ટેબ પરનો **બંધ** રિપોર્ટ દરેક લાભ સમાવે છે: શું સિદ્ધ થયું અને શું હજુ આવવાનું છે.',
        ],
        'intake' => [
            'nav' => 'પ્રસ્તાવ અને મંજૂરી',
            'title' => 'પ્રોજેક્ટનો પ્રસ્તાવ મૂકવો, અને તેને મંજૂર કરવો',
            'intro' => 'ફોર્મ પરના "શું અમને ... મળી શકે" થી મંજૂર પ્રોજેક્ટ સુધી, તેના કારણ લખેલા સાથે.',
            'p1' => 'કોઈપણ ફોર્મ પ્રોજેક્ટનો પ્રસ્તાવ મૂકી શકે. **ફોર્મ**માં, ફોર્મ ખોલો, **આગળ શું થાય છે** પર જાઓ અને "સબમિટ થાય ત્યારે" હેઠળ **પ્રોજેક્ટ પ્રસ્તાવ બનાવો** ઉમેરો (અથવા "મંજૂર થાય ત્યારે", જે ફોર્મ પહેલા સાઇન-ઓફ થાય છે તેના માટે). તેના બોક્સ ખાલી રાખો અને પ્રોજેક્ટનું નામ ફોર્મ અને મોકલનારના નામ પરથી પડે છે, તેનો સારાંશ તેમના જવાબો છે અને તે તેમની કંપનીનો છે; અથવા તે ભરો - નામ, શા માટે જરૂરી છે, અંદાજિત ખર્ચ, અપેક્ષિત લાભ, ક્યાં સુધીમાં જોઈએ, કેવી રીતે ચલાવાય, પ્રાથમિકતા, પ્રોજેક્ટ મેનેજર - જવાબોનો ઉપયોગ કરીને, જેમ કે {{submission.fields.Budget}}. એ જ ક્રિયા **વર્કફ્લો**ના કોઈપણ નિયમમાં કામ કરે છે.',
            'p2' => 'પ્રસ્તાવ તેની ઝાંખી પર **પ્રસ્તાવ** પેનલ બતાવે છે - કોણે મૂક્યો અને કયા ફોર્મ પર, અંદાજિત ખર્ચ, અપેક્ષિત લાભ અને શા માટે જરૂરી છે - અને પોર્ટફોલિયો પર **મંજૂરીની રાહ** ચિપ અને વ્યૂ. તે મંજૂર ન થાય ત્યાં સુધી તે પ્રસ્તાવિત રહી શકે અથવા રદ થઈ શકે, બીજું કંઈ નહીં. મંજૂર કરનાર **મંજૂર કરો** દબાવે છે (તે તેના પ્રોજેક્ટ મેનેજર માટે શરૂ કરવા પ્રસ્તાવિત રહે છે, અથવા તરત શરૂ થાય છે - એક સેટિંગ) અથવા કારણ સાથે **નકારો** (તે રદ થાય છે; કંઈ કાઢી નંખાતું નથી). મંજૂર કરનારાઓને નવા પ્રસ્તાવ વિશે બેલ પર જાણ થાય છે; જેમણે પ્રસ્તાવ મૂક્યો તેમને નિર્ણય જાણ થાય છે, અને "પ્રોજેક્ટ પ્રસ્તાવ મંજૂર અથવા નકારાય છે" પરનો વર્કફ્લો ફોર્મ પર પૂછનાર કોઈને ઈમેઇલ કરી શકે છે.',
            'p3' => 'Projects - Settings - General નક્કી કરે છે કે કયા નવા પ્રોજેક્ટને મંજૂરી જોઈએ (ફોર્મ પર પ્રસ્તાવિત - ડિફોલ્ટ -, દરેક નવો પ્રોજેક્ટ, કે કોઈ નહીં), કોણ મંજૂર કરે (Projects સંભાળતા લોકો, અથવા નામાંકિત વ્યક્તિ - Manage Projects પણ હંમેશા નિર્ણય લઈ શકે) અને મંજૂર કરવાથી શું થાય. સેટિંગ ચાલુ થયા પહેલાં બનેલા પ્રોજેક્ટ પર ક્યારેય અસર થતી નથી.',
        ],
        'control' => [
            'nav' => 'ચેન્જ કંટ્રોલ',
            'title' => 'ચેન્જ કંટ્રોલ: બેઝલાઇન અને ચેન્જ રિક્વેસ્ટ',
            'intro' => 'શું નક્કી થયું હતું, ત્યારથી યોજના કેટલી ખસી ગઈ છે, અને તેને ખસેડવા માટે કોણે સંમતિ આપી.',
            'p1' => '**બેઝલાઇન** યોજનાને નક્કી થયા પ્રમાણે નોંધે છે: શરૂઆત અને લક્ષ્ય સમાપ્તિ, આયોજિત બજેટ, ટાસ્ક અને અંદાજિત કલાકો, Must આઇટમ્સ, તેમજ દરેક તબક્કો, માઇલસ્ટોન અને બજેટ લાઇન. ચેન્જ કંટ્રોલ ટેબ (તબક્કાવાર પ્રોજેક્ટ્સ માટે ચાલુ; બીજા માટે ટૂલ્સ હેઠળ ચાલુ કરો) તેની સરખામણી યોજનાની હાલની સ્થિતિ સાથે કરે છે - સમાપ્તિ પર **+17 દિવસ**, બજેટ પર **+£4,950 (+20%)** - અને શું ખસ્યું તે આઇટમ પ્રમાણે બતાવે છે: માઇલસ્ટોન બે અઠવાડિયા મોડો, વધી ગયેલી બજેટ લાઇન, ઉમેરાયેલી Must આઇટમ. તે બેઝલાઇન સામે માપવા માટે **સરખામણી કરો** હેઠળ જૂની બેઝલાઇન પસંદ કરો. જાતે લેવા માટે **બેઝલાઇન** દબાવો, ઇચ્છો તો લેબલ સાથે; બેઝલાઇન ક્યારેય સંપાદિત થતી નથી, તેની જગ્યાએ નવી લેવાય છે.',
            'p2' => '**ચેન્જ રિક્વેસ્ટ** નક્કી થયેલી યોજના ખસે તે પહેલાં તેને ખસેડવા માટે વિનંતી કરે છે: ફેરફાર શું છે, શા માટે, અને તે સમય (દિવસો, + એટલે મોડું), ખર્ચ (+ વધારે, - બચત) અને સ્કોપ પર શું અસર કરે છે. **ઉઠાવો** દબાવો. જે વ્યક્તિએ તે ઉઠાવી હોય તે રાહ દરમિયાન તેને સંપાદિત કરી શકે છે અથવા પાછી ખેંચી શકે છે. જ્યારે તે **મંજૂર** થાય, ત્યારે નવી બેઝલાઇન લેવાય છે - બદલાયેલી યોજના નક્કી થયેલી યોજના બની જાય છે - અને, ડિફોલ્ટ રૂપે, લક્ષ્ય સમાપ્તિ તેના દિવસો જેટલી ખસે છે અને તેનો ખર્ચ તેના નામની બજેટ લાઇન બને છે. **નકારવાથી** નિર્ણય નોંધાય છે અને કંઈ બદલાતું નથી. રિક્વેસ્ટ ક્યારેય કાઢી નંખાતી નથી: યોજના કેમ ખસી તેનો તે રેકોર્ડ છે, અને દરેક ઇતિહાસમાં છે. બીજા કોઈએ ઉઠાવેલી રિક્વેસ્ટ વિશે પ્રોજેક્ટ મેનેજરને જાણ કરવામાં આવે છે, અને રાહ જોઈ રહેલી રિક્વેસ્ટ ઝાંખી અને પોર્ટફોલિયો કાર્ડ પર દેખાય છે.',
            'p3' => 'Projects - Settings - General નક્કી કરે છે કે તે તમારા માટે કેવી રીતે કામ કરે: પ્રોજેક્ટ સક્રિય થાય ત્યારે બેઝલાઇન **જાતે** લેવાય, અથવા ત્યારે **અને** દરેક તબક્કો શરૂ થાય ત્યારે (ડિફોલ્ટ), અથવા ફક્ત હાથે; ચેન્જ રિક્વેસ્ટનો **નિર્ણય કોણ કરે** - પ્રોજેક્ટ મેનેજર અથવા Projects સંભાળનાર કોઈપણ (ડિફોલ્ટ), પ્રોજેક્ટની ટીમમાંનું કોઈપણ, અથવા ફક્ત Projects સંભાળનાર લોકો; રિક્વેસ્ટ ઉઠાવનાર વ્યક્તિ તેનો **નિર્ણય પણ** કરી શકે કે નહીં; અને મંજૂરી **યોજના પણ ખસેડે** કે ફક્ત નવી બેઝલાઇન લે.',
        ],
        'announce' => [
            'nav' => 'વિક્ષેપની જાહેરાત',
            'title' => 'Service Status પર વિક્ષેપની જાહેરાત',
            'intro' => '"મૂવ ડે: શનિવારે ફોન બંધ" - તે થાય તે પહેલાં બધાને જણાવવામાં આવે છે.',
            'p1' => 'કનેક્શન્સ ટેબમાં Service Status ખોલી શકનાર લોકો માટે **Service Status** પેનલ છે. **જાહેર કરો** દબાવો, તેને શીર્ષક, શરૂઆત અને સમાપ્તિનો સમય, લોકોએ શું જાણવું જોઈએ અને અસરગ્રસ્ત સેવાઓ આપો (તમે બીજી અસર પસંદ ન કરો ત્યાં સુધી જાળવણી). ડિફોલ્ટ રૂપે તે **આયોજિત જાળવણી** બને છે: તે તરત Service Status પર આગામી તરીકે દેખાય છે, શરૂ થાય ત્યારે તે સેવાઓ પર ઘટના બને છે, અને સમાપ્ત થાય ત્યારે ઉકેલાય છે. શરૂ થાય તે પહેલાં ક્રોસથી તેને પાછી ખેંચો. પેનલ પ્રોજેક્ટે જાહેર કરેલી દરેક બાબત બતાવે છે, અને જાહેર કરવું તેમજ પાછું ખેંચવું બંને પ્રોજેક્ટના ઇતિહાસમાં જાય છે.',
            'p2' => '**Projects - Settings - General - Service Status પર વિક્ષેપની જાહેરાત** નક્કી કરે છે કે જાહેર કરો શું કરે: આયોજિત જાળવણી તરીકે (ડિફોલ્ટ), સીધી ઘટના તરીકે, અથવા બિલકુલ નહીં. પ્રોજેક્ટ કાઢી નાખવાથી તેણે જાહેર કરેલી બાબતો Service Status પર રહે છે: તે વાસ્તવિક સેવાઓ પરનું વાસ્તવિક કામ છે.',
        ],
        'reports' => [
            'nav' => 'બ્રીફિંગ અને રિપોર્ટ',
            'title' => 'AI પ્રોજેક્ટ મેનેજર: બ્રીફિંગ અને રિપોર્ટ',
            'intro' => 'આ અઠવાડિયે તમારે શું કરવું જરૂરી છે તેનું બ્રીફિંગ, અને તમારા તપાસવા માટે તૈયાર કરેલા સ્ટેટસ રિપોર્ટ.',
            'p1' => '**Projects - Settings - AI** માં AI પ્રોવાઇડર સેટ થઈ જાય પછી, પ્રોજેક્ટની ઝાંખીમાં **બ્રીફિંગ** પેનલ આવે છે. **મને જણાવો** દબાવો અને AI પ્રોજેક્ટ વાંચે છે - તારીખો, હેલ્થ, સહનશીલતા, તબક્કા, મુદતવીતી અને આગામી ટાસ્ક, જોખમો અને ઇશ્યૂ, બજેટ અને છેલ્લા અઠવાડિયાના ફેરફારો, અને 3.3.0 થી પ્રાથમિકતા, માઇલસ્ટોન, અંદાજો, નિર્ણયો, ચેન્જ રિક્વેસ્ટ, અર્ન્ડ વેલ્યુ, લાભો, કયા ટાસ્ક બીજા પર નિર્ભર છે અને ક્રિટિકલ પાથ, હજુ ખુલ્લી ગેટ ચેકલિસ્ટ આઇટમ્સ અને સ્ટેકહોલ્ડર મેપ પણ - અને શું ધ્યાન માંગે છે તેના ચારથી સાત ટૂંકા મુદ્દા લખે છે, સૌથી મહત્વનો પહેલા. તાજેતરનું બ્રીફિંગ બધા માટે પેજ પર રહે છે; નવું વધુમાં વધુ દર 10 મિનિટે તૈયાર થાય છે, કારણ કે દરેક એક પ્રોવાઇડરને કૉલ છે.',
            'p2' => '**રિપોર્ટ્સ** ટેબમાં પ્રોજેક્ટના હાઇલાઇટ, એક્સેપ્શન, ચેકપોઇન્ટ અને ક્લોઝર રિપોર્ટ છે. પ્રકાર અને સમયગાળો પસંદ કરો અને AI પાસે લખાવવા માટે **ડ્રાફ્ટ** દબાવો, અથવા પોતાનો શરૂ કરવા **લખો** દબાવો. પ્રોજેક્ટમાં ફેરફાર કરી શકનાર કોઈપણ ડ્રાફ્ટ બનાવી, સંપાદિત કરી અને કાઢી શકે છે. **મંજૂર કરવું** પ્રોજેક્ટ મેનેજર, પ્રોજેક્ટ બનાવનાર વ્યક્તિ અને Projects સંભાળનાર લોકો માટે છે - મંજૂર થયેલો રિપોર્ટ અંતિમ છે, સંપાદિત થઈ શકતો નથી, અને બોર્ડ તે જ વાંચે છે. દરેક રિપોર્ટ બતાવે છે કે AI એ તેનો ડ્રાફ્ટ કર્યો હતો કે નહીં અને ત્યારથી કોઈ વ્યક્તિએ તેમાં ફેરફાર કર્યો છે કે નહીં. **નકલ** તેને ઇમેઇલ અથવા દસ્તાવેજમાં પેસ્ટ કરવા માટે ક્લિપબોર્ડ પર મૂકે છે.',
            'p3' => 'AI ફક્ત તે જ જુએ છે જે પૂછનાર વ્યક્તિ જોઈ શકે છે: જે વ્યક્તિ પાસે તે મોડ્યુલ નથી તેના માટે ટિકિટ, ચેન્જ અને Service Status બાકાત રહે છે. તેને ફક્ત પ્રોજેક્ટમાં જે છે તે જ જણાવવા અને કંઈક ખબર ન હોય ત્યાં તેમ કહેવા જણાવાયેલું છે - પણ તે હજુ ખોટું હોઈ શકે છે, તેથી મંજૂર કરતાં પહેલાં ડ્રાફ્ટ વાંચો. તમે FreeITSM જે ભાષામાં વાપરો છો તેમાં તે લખે છે. લોકોએ પ્રોજેક્ટમાં લખેલું લખાણ ડેટા તરીકે પસાર થાય છે, ક્યારેય સૂચનાઓ તરીકે નહીં.',
            'p4' => '**રિપોર્ટ જાતે ડ્રાફ્ટ કરો** (રિપોર્ટ્સ ટેબ પર): પ્રોજેક્ટ સક્રિય હોય ત્યારે દર અઠવાડિયે, દર બે અઠવાડિયે અથવા દર મહિને, સમયગાળાની શરૂઆતમાં હાઇલાઇટ, ચેકપોઇન્ટ અથવા એક્સેપ્શન રિપોર્ટ ડ્રાફ્ટ થાય છે - AI સેટ હોય તો તેના દ્વારા, નહીં તો લખવા માટેના તથ્યો સાથે - અને પ્રોજેક્ટ મેનેજરને જણાવાય છે. તે પ્રોજેક્ટ મેનેજરની ઍક્સેસથી લખાય છે, તેથી તેમાં ફક્ત તે જ હોય છે જે તેઓ જોઈ શકે. તે ક્યારેય જાતે મંજૂર થતો નથી. મંજૂર રિપોર્ટ પર **મોકલો** તેને તમે ટિક કરેલા પ્રોજેક્ટના સભ્યો અને અન્ય કોઈપણ સરનામાં પર ઇમેઇલ કરે છે, ઉપર વૈકલ્પિક નોંધ સાથે; રિપોર્ટ બતાવે છે કે તે કોને અને ક્યારે ગયો.',
        ],
        'assistant' => [
            'nav' => 'AIને પૂછો',
            'title' => 'AIને પૂછો - પ્રોજેક્ટ આસિસ્ટન્ટ',
            'intro' => 'એક પ્રોજેક્ટ વિશે AI પ્રોજેક્ટ મેનેજર સાથે વાતચીત, જે તેને વાંચી શકે છે અને ફેરફારો સૂચવી શકે છે.',
            'p1' => 'પ્રોજેક્ટ પર, **AIને પૂછો** (ઉપર જમણે) આસિસ્ટન્ટને અંદર સ્લાઇડ કરે છે. તે પ્રોજેક્ટને તમે જેમ વાંચી શકો તેમ વાંચે છે - જે તમે પોતે ખોલી ન શકો તે કંઈ નહીં - અને સાદા શબ્દોમાં જવાબ આપે છે, પછી ભલે તમે ક્યારેય પ્રોજેક્ટ ચલાવ્યો ન હોય કે PRINCE2 મોઢે જાણતા હો. Projects - Settings - AI માં AI પ્રોવાઇડર સેટ થઈ જાય પછી.',
            'p2' => 'તે શોધી કાઢે છે કે પ્રોજેક્ટ કેટલો સેટ થયો છે. ફક્ત નામ જેટલા પ્રોજેક્ટને **કોચ** મળે છે: તે શેના વિશે છે, પૂર્ણ થવું કેવું દેખાય, લગભગ ક્યારે, કોણ સંકળાયેલું છે - અને પછી સૂચવેલ સેટ-અપ: ધ્યેય, તારીખો, ચલાવવાની રીત, તબક્કા, શરૂઆતના ટાસ્ક, માઇલસ્ટોન અને સંભવિત જોખમો. ચાલુ પ્રોજેક્ટને **બધું નજર હેઠળ રાખવામાં** મદદ મળે છે: શું મુદતવીતી છે, ઊંચા જોખમો, ચૂકી ગયેલા માઇલસ્ટોન, રાહ જોતી ચેન્જ રિક્વેસ્ટ. વાતચીત નીચેના બટનો શરૂ કરવા માટે પ્રશ્ન સૂચવે છે.',
            'p3' => '**તે પ્રોજેક્ટને ક્યારેય જાતે બદલતો નથી.** સૂચવેલા ફેરફારો કાર્ડ તરીકે આવે છે - દરેક માટે એક બૉક્સ, બધા ટિક કરેલા - **લાગુ કરો** અને **અવગણો** સાથે. લાગુ કરો ટિક કરેલાને બરાબર એવી રીતે કરે છે જાણે તમે સ્ક્રીન પર કર્યા હોય, તમારી પરવાનગીઓ સાથે, અને તે ઇતિહાસમાં તમારા તરીકે દેખાય છે. જો તમને પ્રોજેક્ટ બદલવાની પરવાનગી ન હોય, તો તે તેની જગ્યાએ સલાહ આપે છે.',
            'p4' => '**તે યાદ રાખે છે.** પ્રોજેક્ટ પરની તમારી વાતચીત સચવાય છે, અને જૂના ભાગો ટૂંકી યાદમાં સમાવાય છે, તેથી તમે જ્યાં અટકયા હતા ત્યાંથી આગળ વધો છો; થોડો સમય દૂર રહ્યા પછી તે ત્યારથી શું બદલાયું તેનાથી શરૂ થાય છે. **ફરી શરૂ કરો** તેને ભૂલાવી દે છે. Projects - Settings - General - *AI આસિસ્ટન્ટની યાદ* તેને દરેક માટે એક-એક વાતચીતને બદલે આખી પ્રોજેક્ટ ટીમ વહેંચે તેવી એક વાતચીત બનાવે છે.',
        ],
        'companies' => [
            'nav' => 'કંપનીઓ',
            'title' => 'પ્રોજેક્ટ્સ અને કંપનીઓ',
            'intro' => 'દરેક પ્રોજેક્ટ એક કંપનીનો હોય છે.',
            'p1' => 'એક કરતાં વધુ કંપનીવાળા ઇન્સ્ટોલ પર, પ્રોજેક્ટ તે કંપનીનો હોય છે જેમાં તે બનાવાયો હતો (અથવા તમે પસંદ કરેલી), અને તેના ટાસ્ક પણ ત્યાંના હોય છે. તમે ફક્ત તે કંપનીઓના પ્રોજેક્ટ જુઓ છો જે તમે જોઈ શકો છો, અને બધી કંપનીઓનું દૃશ્ય તેમને સાથે બતાવે છે. બીજી કંપનીનો ટાસ્ક પ્રોજેક્ટમાં મૂકી શકાતો નથી.',
        ],
        'settings' => [
            'nav' => 'સેટિંગ્સ',
            'title' => 'સેટિંગ્સ અને પરવાનગીઓ',
            'intro' => 'પ્રોજેક્ટ્સ બનાવવા, બદલવા અને કાઢી નાખવાની પરવાનગી કોને છે, અને મોડ્યુલ વાપરે છે તે શબ્દો અને મર્યાદાઓ.',
            'p1' => '**Projects - Settings** માં સાત ટેબ છે, અને દરેકને **System - Roles** પર આપેલી પોતાની પરવાનગી જોઈએ; Manage Projects સાતેય આવરી લે છે. જેની પાસે એકેય નથી તેને એવું પેજ દેખાય છે જે કહે છે કે ગોઠવવા જેવું કંઈ નથી.',
            'general_d' => 'બીજી રીત ન પસંદ કરો ત્યાં સુધી નવો પ્રોજેક્ટ કેવી રીતે ચલાવાય, પ્રોજેક્ટ્સ કોણ બનાવી શકે, કોણ બદલી શકે, કયા તારીખો કૅલેન્ડર પર જાય અને Service Status પર વિક્ષેપની જાહેરાત કેવી રીતે થાય. સાથે પ્રાથમિકતાના શબ્દો, પોર્ટફોલિયોનો શરૂઆતનો ક્રમ, બર્ન-અપ શું ગણે, ચેન્જ કંટ્રોલ (આપોઆપ બેઝલાઇન, નિર્ણય કોણ કરે, પોતાનું નક્કી કરવું, મંજૂરી શું કરે), ઝાંખી પરનું ટૂલબોક્સ (ચાલુ), AI આસિસ્ટન્ટની યાદ (દરેક વ્યક્તિની પોતાની), કોન્ટ્રાક્ટર્સને ઇમેઇલ કરવા કે નહીં (બંધ), મુદતવીતી ટાસ્કનો ડાઇજેસ્ટ (સાપ્તાહિક) અને નડજ (3 દિવસ પછી), નવો પ્રોજેક્ટ કોણ જોઈ શકે (Projects ધરાવતા બધા), ખુલ્લી ગેટ ચેકલિસ્ટ આઇટમ go ને રોકે કે નહીં (રોકે છે), લાભોની સમીક્ષા કેટલી વાર થાય (દર 3 મહિને) અને કોને યાદ અપાય, અને કયા પ્રસ્તાવોને મંજૂરી જોઈએ, કોણ મંજૂર કરે અને મંજૂરી શું કરે.',
            'health_d' => 'જીવંત પ્રોજેક્ટ ક્યારે એમ્બર કે લાલ થાય: લક્ષ્ય કેટલું નજીક છે, ત્યાં સુધીમાં કેટલું પૂરું થવું જોઈએ, કેટલું મુદતવીતી કામ તેને લાલ બનાવે અને કેટલી નવી લિંક થયેલી ટિકિટ તેને એમ્બર બનાવે; ચૂકી ગયેલો માઇલસ્ટોન, અથવા તારીખ વીતી ગયેલી ડિપેન્ડન્સી કે નિર્ણય શું કરે (ડિફોલ્ટ રૂપે એમ્બર); અને કેપેસિટી પેજના અઠવાડિયાના કલાકો, ખેંચાયેલું સ્તર, ઘણા પ્રોજેક્ટ્સ, કામના દિવસો અને રોટા શિફ્ટ ગણાય કે નહીં.',
            'roles_d' => 'પ્રોજેક્ટના લોકો ટેબ પર આપવામાં આવતી ભૂમિકાઓ. ક્રમ બદલવા ખેંચો; ભૂમિકા આપવાનું બંધ કરવા પ્રોજેક્ટ્સ પર ઉપલબ્ધ અનટિક કરો; એકને કાઢી નાખવાથી તેના ધારકો તેમના પ્રોજેક્ટ્સ પર કોઈ ભૂમિકા વિના રહે છે.',
            'raid_d' => 'સંભાવના સ્કેલ અને અસર સ્કેલના પગથિયાં માટેના પાંચ શબ્દો, સૌથી નીચેથી શરૂ કરીને.',
            'ai_d' => 'બ્રીફિંગ અને ડ્રાફ્ટ કરેલા રિપોર્ટ વાપરે છે તે AI પ્રોવાઇડર, મોડેલ અને કી. કી તમારી સંસ્થાના પૈસા ખર્ચે છે, તેથી આની પોતાની પરવાનગી છે.',
            'budget_d' => 'નવા પ્રોજેક્ટ્સ માટેનું ચલણ, પ્રોજેક્ટ પોતાનું પસંદ કરી શકે કે નહીં, નોંધાયેલા સમયનો ખર્ચ કેવી રીતે ગણાય, અને કલાકદીઠ દરો - ડિફોલ્ટ અને દરેક વિશ્લેષકનો - દરેક એક તારીખથી. સાથે મંજૂર ઓવરસ્પેન્ડ શું ખર્ચાયું તે માપે (ડિફોલ્ટ) કે અનુમાન, અને ખુલ્લા ટાસ્ક પર હજુ અંદાજિત કલાકો અનુમાનમાં ગણાય કે નહીં (ગણાય છે).',
            'templates_d' => 'નવા પ્રોજેક્ટ્સ માટે આપવામાં આવતા ટેમ્પ્લેટ: બિલ્ટ-ઇન ટેમ્પ્લેટ છુપાવો, અને પ્રોજેક્ટમાંથી સાચવેલા ટેમ્પ્લેટનું નામ બદલો, બંધ કરો અથવા કાઢી નાખો. આ જ પરવાનગી કોઈને પ્રોજેક્ટને ટેમ્પ્લેટ તરીકે સાચવવા દે છે.',
            'p2' => '**પ્રોજેક્ટ્સ કોણ બનાવી શકે** તે કાં તો Projects ખોલી શકનાર કોઈપણ (ડિફોલ્ટ) અથવા ફક્ત Projects સંભાળનાર લોકો છે. **પ્રોજેક્ટ કોણ બદલી શકે** તે કાં તો તેની ટીમ (ડિફોલ્ટ) અથવા Projects ખોલી શકનાર કોઈપણ છે. પ્રોજેક્ટની ટીમ એટલે તેનો પ્રોજેક્ટ મેનેજર, તેને બનાવનાર વ્યક્તિ અને તેના સભ્યો, જેમાં સભ્ય તરીકેની ટીમમાંના વિશ્લેષકો પણ આવે. Projects સંભાળનાર લોકો અને એડમિનિસ્ટ્રેટર્સ ગમે તે પ્રોજેક્ટ હંમેશા બદલી શકે છે.',
            'p3' => 'પ્રોજેક્ટ **કાઢી નાખવો** સેટિંગ્સ ગમે તે કહે, હંમેશા તેના પ્રોજેક્ટ મેનેજર, તેને બનાવનાર વ્યક્તિ અને Projects સંભાળનાર લોકો સુધી મર્યાદિત છે. જ્યારે તમને પ્રોજેક્ટ બદલવાની પરવાનગી ન હોય, ત્યારે તેનું પેજ તે કરતા બટનો છુપાવે છે, અને સર્વર ફેરફાર કોઈપણ રીતે નકારે છે.',
        ],
        'api' => [
            'nav' => 'API',
            'title' => 'API દ્વારા પ્રોજેક્ટ્સ',
            'intro' => 'સ્ક્રિપ્ટ્સ, અન્ય સિસ્ટમ્સ અને AI આસિસ્ટન્ટ્સ માટે.',
            'p1' => 'પ્રોજેક્ટ્સ REST API દ્વારા વાંચી અને બદલી શકાય છે, અને MCP સર્વર દ્વારા AI આસિસ્ટન્ટ વાંચી શકે છે. બંને **System - API** માં સેટ થાય છે, અને API કી ફક્ત તે કંપનીઓ સુધી પહોંચે છે જે તેનો વિશ્લેષક જોઈ શકે છે.',
            'p2' => '**War Room** માં, Warbot પ્રોજેક્ટ્સ વિશેના પ્રશ્નોના પણ જવાબ આપે છે - "કયા પ્રોજેક્ટ્સ ટ્રેક પર નથી?", "આ અઠવાડિયે કોઈ પ્રોજેક્ટ મોટું કંઈ કરી રહ્યો છે?" - અથવા **/projects**, **/project** અને **/dates** વાપરો. તે ફક્ત Projects ખોલી શકનાર લોકોને આપવામાં આવે છે, તેઓ જોઈ શકે તેવા પ્રોજેક્ટ્સ વિશે જવાબ આપે છે, અને ક્યારેય પૈસાનો ઉલ્લેખ કરતું નથી: ચેનલમાંના બધા તેના જવાબો વાંચે છે.',
        ],
    ],
